                case 'n': // newline
                    sb.append(System.lineSeparator());
                    break;
                case '%': // literal %
                    sb.append('%');
                    break;
                default: // unknown specifier, keep as is
                    sb.append('%').append(spec);
                    break;
            }
        }
    }
    return sb.toString();
