public String format(LoggingEvent event) {
    // Assume this.pattern contains the conversion pattern string.
    // Simple replacement for a subset of common conversion keywords.
    String fmt = (this.pattern != null) ? this.pattern : "%d{HH:mm:ss} [%t] %-5level %logger{36} - %msg%n";

    // Replace date conversions – %d{pattern}
    java.util.regex.Pattern datePattern = java.util.regex.Pattern.compile("%d\\{([^}]+)\\}");
    java.util.regex.Matcher dateMatcher = datePattern.matcher(fmt);
    java.lang.StringBuffer dateSb = new java.lang.StringBuffer();
    while (dateMatcher.find()) {
        String dateFmt = dateMatcher.group(1);
        java.time.format.DateTimeFormatter formatter;
        try {
            formatter = java.time.format.DateTimeFormatter.ofPattern(dateFmt);
        } catch (IllegalArgumentException e) {
            // Fallback to ISO_INSTANT if the pattern is invalid
            formatter = java.time.format.DateTimeFormatter.ISO_INSTANT;
        }
        String dateStr = java.time.ZonedDateTime.now().format(formatter);
        dateMatcher.appendReplacement(dateSb, java.util.regex.Matcher.quoteReplacement(dateStr));
    }
    dateMatcher.appendTail(dateSb);
    fmt = dateSb.toString();

    // Replace date conversion without format – %d
    if (fmt.contains("%d")) {
        String dateStr = java.time.Instant.now().toString();
        fmt = fmt.replace("%d", dateStr);
    }

    // Replace level – %p
    if (fmt.contains("%p")) {
        fmt = fmt.replace("%p", (event.getLevel() != null) ? event.getLevel().toString() : "UNKNOWN");
    }

    // Replace thread name – %t
    if (fmt.contains("%t")) {
        fmt = fmt.replace("%t", (event.getThreadName() != null) ? event.getThreadName() : "unknown");
    }

    // Replace logger name – %c or %logger
    if (fmt.contains("%c")) {
        fmt = fmt.replace("%c", (event.getLoggerName() != null) ? event.getLoggerName() : "unknown");
    }
    if (fmt.contains("%logger")) {
        fmt = fmt.replace("%logger", (event.getLoggerName() != null) ? event.getLoggerName() : "unknown");
    }

    // Replace message – %m or %msg
    if (fmt.contains("%m")) {
        fmt = fmt.replace("%m", (event.getMessage() != null) ? event.getMessage() : "");
    }
    if (fmt.contains("%msg")) {
        fmt = fmt.replace("%msg", (event.getMessage() != null) ? event.getMessage() : "");
    }

    // Replace newline – %n
    if (fmt.contains("%n")) {
        fmt = fmt.replace("%n", System.lineSeparator());
    }

    return fmt;
}

public String format(LoggingEvent event){
    // Use the conversion pattern if set; otherwise default to a common pattern
    String pattern = (this.conversionPattern != null) ? this.conversionPattern : "%d [%t] %-5p %c - %m%n";
    StringBuilder sb = new StringBuilder();

    java.util.Date date = new java.util.Date(event.getTimeStamp());
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");

    int i = 0;
    while (i < pattern.length()){
        char ch = pattern.charAt(i);
        if (ch == '%' && i + 1 < pattern.length()){
            char next = pattern.charAt(i + 1);
            switch (next){
                case 'd':
                    sb.append(sdf.format(date));
                    i += 2;
                    break;
                case 't':
                    sb.append(event.getThreadName());
                    i += 2;
                    break;
                case 'p':
                    sb.append(event.getLevel());
                    i += 2;
                    break;
                case 'c':
                    sb.append(event.getLoggerName());
                    i += 2;
                    break;
                case 'm':
                    sb.append(event.getMessage());
                    i += 2;
                    break;
                case 'n':
                    sb.append(System.lineSeparator());
                    i += 2;
                    break;
                case '-':
                    // Width specification ignored for simplicity
                    i += 2;
                    break;
                default:
                    sb.append(ch);
                    i++;
            }
        } else {
            sb.append(ch);
            i++;
        }
    }

    // Append exception stack trace if present
    if (event.getThrowableInformation() != null){
        Throwable t = event.getThrowableInformation().getThrowable();
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        t.printStackTrace(pw);
        pw.flush();
        sb.append(sw.toString());
    }

    return sb.toString();
}

