private int parseEndOfLine(String headerPart, int end) {
    int length = headerPart.length();
    int i = end + 1;
    while (i < length - 1) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
        i++;
    }
    // Return -1 if no CRLF sequence is found
    return -1;
}

