    int pos = end + 1; // start looking after the last processed byte
    while (pos + 1 < headerPart.length()) {
        if (headerPart.charAt(pos) == '\r' && headerPart.charAt(pos + 1) == '\n') {
            // return the index of the '\r' that starts the CRLF sequence
            return pos;
        }
        pos++;
    }
    // If no CRLF found, indicate failure with -1
    return -1;
}

