    for (int i = end; i < headerPart.length() - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i; // Return the index of the CR character that starts the line break
        }
    }
    // If no CRLF sequence is found, indicate the end of line was not located
    return -1;
}

private int parseEndOfLine(String headerPart,int end){
    if(headerPart == null || headerPart.isEmpty()){
        return -1;
    }
    int len = headerPart.length();
    // start searching after the last processed byte
    int start = end + 1;
    for(int i = start; i <= len - 2; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    // If \r\n not found, return -1
    return -1;
}

