public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        // Nothing to schedule
        return;
    }
    // Collect all files/directories, ensuring children before parents
    java.util.List<File> toDelete = new java.util.ArrayList<>();
    java.util.Deque<File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        File current = stack.pop();
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children != null) {
                // Push children onto stack so they get processed before their parent
                for (File child : children) {
                    stack.push(child);
                }
            }
        }
        toDelete.add(current);
    }
    // Schedule deletion on JVM exit (children first, then parents)
    for (File f : toDelete) {
        f.deleteOnExit();
    }
}

