    if (file == null) {
        throw new NullPointerException("file");
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children == null) {
            throw new IOException("Unable to list folder: " + file);
        }
        for (File child : children) {
            forceDeleteOnExit(child);
        }
    }
    file.deleteOnExit();
}

