@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Partition vertices into two sets for bipartite graph.
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    // Attempt to use key prefixes "L" and "R" to decide side
    for (Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        if (key.startsWith("L") || key.startsWith("l")) {
            left.add(entry.getValue());
        } else if (key.startsWith("R") || key.startsWith("r")) {
            right.add(entry.getValue());
        }
    }
    // If we couldn't find any prefixes, split the vertices into two halves.
    if (left.isEmpty() && right.isEmpty()){
        int i = 0;
        for (V v : resultMap.values()){
            if (i++ < resultMap.size()/2) left.add(v);
            else right.add(v);
        }
    }
    // Add edges between every vertex in left and every vertex in right.
    for (V u : left){
        for (V v : right){
            if (!target.containsEdge(u, v)){
                target.addEdge(u, v);
            }
        }
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
