    for (V vertex : resultMap.values()){
        target.addVertex(vertex);
    }
    // Collect vertices in a list to index them
    List<V> vertices = new ArrayList<>(resultMap.values());
    int total = vertices.size();
    int partitionSize = total / 2;
    // Construct all possible edges between the two halves
    for (int i = 0; i < partitionSize; i++){
        V left = vertices.get(i);
        for (int j = partitionSize; j < total; j++){
            V right = vertices.get(j);
            // Add an edge between left and right
            target.addEdge(left, right);
        }
    }
}

