public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    // Compute the serialized size of the message
    int size = schema.serializedSize(message, buffer);
    // Write the size as a Varint32 prefix
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    codedOut.writeRawVarint32(size);
    // Serialize the actual message data
    schema.writeTo(message, codedOut, buffer);
    codedOut.flush();
    return size;
}

public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (message == null) {
        throw new NullPointerException("message");
    }
    // Compute the size of the message once.
    int size = schema.getCachedSize(message);
    // Write the size prefix as a varint.
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);
    // Write the message itself.
    schema.writeTo(cos, message);
    cos.flush();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the size of the serialized message
    int size = schema.getCachedSize(message);
    // Allocate a byte buffer large enough for the message
    byte[] data = new byte[size];
    // Serialize the message into the byte buffer
    com.google.protobuf.CodedOutputStream codedOut = com.google.protobuf.CodedOutputStream.newInstance(data);
    schema.writeTo(message, codedOut);
    int actualSize = codedOut.getTotalBytesWritten();
    // Write the length prefix using varint encoding
    int v = actualSize;
    while ((v & ~0x7F) != 0) {
        out.write((v & 0x7F) | 0x80);
        v >>>= 7;
    }
    out.write(v);
    // Write the serialized message bytes
    out.write(data, 0, actualSize);
    return actualSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message into the supplied buffer
    schema.write(message, buffer);

    // Obtain the raw data and its size from the buffer
    int size = buffer.position();      // number of bytes written
    byte[] rawData = buffer.array();   // underlying byte array

    // Write the length prefix as a varint
    CodedOutputStream head = CodedOutputStream.newInstance(out);
    head.writeUInt32NoTag(size);
    head.flush();

    // Write the serialized message body
    out.write(rawData, 0, size);

    // Reset the buffer for future reuse
    buffer.clear();

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message, buffer);
    // Encode the size as a varint and write it to the output stream
    int tmp = size;
    while ((tmp & ~0x7F) != 0) {
        out.write((tmp & 0x7F) | 0x80);
        tmp >>>= 7;
    }
    out.write(tmp);
    // Write the message itself using a CodedOutputStream
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    schema.writeTo(codedOut, message);
    codedOut.flush();
    return size;
}

