        return;
    }
    try {
        String output;
        if (layout != null) {
            output = layout.doLayout(event);
        } else {
            // Fallback to the most useful representation we have
            output = event.getFormattedMessage();
            if (output == null) {
                output = event.getMessage();
                if (output == null) {
