        return;
    }
    // Format the event using the layout if available
    String formatted = (getLayout() != null)
            ? getLayout().format(event)
            : (event.getMessage() != null ? event.getMessage().toString() : "");
    try {
        // Write the formatted string to the configured output stream
        byte[] bytes = formatted.getBytes("UTF-8");
        if (outputStream != null) {
            outputStream.write(bytes);
            if (immediateFlush) {
                outputStream.flush();
            }
        } else if (writer != null) {
            writer.write(formatted);
            if (immediateFlush) {
                writer.flush();
