public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pGenericType = (ParameterizedType) genericType;
    Type raw = pGenericType.getRawType();
    if (!(raw instanceof Class<?>)) {
        return null;
    }
    Class<?> rawClass = (Class<?>) raw;

    ParameterizedType matchedPT = null;
    Class<?> curClass = targetType;
    while (curClass != null && matchedPT == null) {
        // check superclass
        Type superT = curClass.getGenericSuperclass();
        if (superT instanceof ParameterizedType) {
            ParameterizedType superPT = (ParameterizedType) superT;
            if (superPT.getRawType() == rawClass) {
                matchedPT = superPT;
                break;
            }
        }
        // check interfaces
        for (Type it : curClass.getGenericInterfaces()) {
            if (it instanceof ParameterizedType) {
                ParameterizedType itPT = (ParameterizedType) it;
                if (itPT.getRawType() == rawClass) {
                    matchedPT = itPT;
                    break;
                }
            }
        }
        curClass = curClass.getSuperclass();
    }
    if (matchedPT == null) {
        return null;
    }
    Type[] actualArgs = matchedPT.getActualTypeArguments();
    Class<?>[] res = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type t = actualArgs[i];
        if (t instanceof Class<?>) {
            res[i] = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type rawT = ((ParameterizedType) t).getRawType();
            if (rawT instanceof Class<?>) {
                res[i] = (Class<?>) rawT;
            } else {
                return null;
            }
        } else {
            return null;
        }
    }
    return res;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        throw new IllegalArgumentException("genericType and targetType must not be null");
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    Type[] actuals = pt.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actuals.length];
    for (int i = 0; i < actuals.length; i++) {
        result[i] = resolveToClass(actuals[i]);
        if (result[i] == null) {
            return null;
        }
    }
    return result;
}

private static Class<?> resolveToClass(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    }
    if (type instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) type).getRawType();
    }
    // GenericArrayType, WildcardType, and TypeVariable cannot be resolved to a concrete Class at runtime
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pType = (ParameterizedType) genericType;
    Type[] args = pType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[args.length];
    for (int i = 0; i < args.length; i++) {
        Type t = args[i];
        Class<?> clazz = null;
        if (t instanceof Class) { // simple class type
            clazz = (Class<?>) t;
        } else if (t instanceof ParameterizedType) { // nested parameterized type
            clazz = (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof WildcardType) { // wildcard, use upper bound if available
            WildcardType w = (WildcardType) t;
            Type[] ub = w.getUpperBounds();
            if (ub.length == 1 && ub[0] instanceof Class) {
                clazz = (Class<?>) ub[0];
            }
        } else if (t instanceof TypeVariable) { // try to resolve via targetType
            clazz = resolveTypeVariable((TypeVariable<?>) t, targetType);
        }
        if (clazz == null) {
            return null;
        }
        result[i] = clazz;
    }
    return result;
}

