    // Attempt to resolve a type variable by walking up the targetType hierarchy
    Class<?> current = targetType;
    while (current != null) {
        // Check superclass generic parameters
        Type generics = current.getGenericSuperclass();
        if (generics instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) generics;
            Type[] actuals = pt.getActualTypeArguments();
            TypeVariable<?>[] params = current.getSuperclass().getTypeParameters();
            for (int i = 0; i < params.length; i++) {
                if (params[i].equals(var)) {
                    Type actual = actuals[i];
                    if (actual instanceof Class) {
                        return (Class<?>) actual;
                    } else if (actual instanceof TypeVariable) {
                        return resolveTypeVariable((TypeVariable<?>) actual, current.getSuperclass());
                    }
                }
            }
        }
        // Check interfaces generic parameters
        for (Type iface : current.getGenericInterfaces()) {
            if (iface instanceof ParameterizedType) {
                ParameterizedType ptIface = (ParameterizedType) iface;
                Type[] actuals = ptIface.getActualTypeArguments();
                TypeVariable<?>[] params = ((Class<?>) ptIface.getRawType()).getTypeParameters();
                for (int i = 0; i < params.length; i++) {
                    if (params[i].equals(var)) {
                        Type actual = actuals[i];
                        if (actual instanceof Class) {
                            return (Class<?>) actual;
                        } else if (actual instanceof TypeVariable) {
                            return resolveTypeVariable((TypeVariable<?>) actual, (Class<?>) ptIface.getRawType());
                        }
                    }
                }
            }
        }
        current = current.getSuperclass();
    }
    return null;
}

