        return null;
    }

    // Extract property maps from both the current and history mappings
    Map<String, Object> currentProps = currentMappings.getProperties();
    Map<String, Object> historyProps = mappings.getProperties();
    if (currentProps == null || historyProps == null) {
        return null;
    }

    // Build a map containing only the fields that are new in the current mapping,
    // excluding the special "_source" field to avoid update conflicts
    Map<String, Object> diffProps = new LinkedHashMap<>();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();
        if ("_source".equals(field)) {
            continue;
        }
        if (!historyProps.containsKey(field)) {
            diffProps.put(field, entry.getValue());
        }
    }

    // If there are no new fields, return null (or you could return an empty mapping)
    if (diffProps.isEmpty()) {
        return null;
    }

    // Construct and return the diff mapping
    Mappings diffMapping = new Mappings();
    diffMapping.setProperties(diffProps);
    return diffMapping;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current index mappings (history mapping)
    Mappings currentMapping = this.mappingService.getMapping(tableName);
    if (currentMapping == null) {
        return null; // No existing mapping to compare with
    }

    // Get the source part of the mappings
    Map<String, Object> currentSource = currentMapping.getSource();
    Map<String, Object> inputSource = mappings.getSource();

    if (currentSource == null) {
        currentSource = new LinkedHashMap<>();
    }
    if (inputSource == null) {
        inputSource = new LinkedHashMap<>();
    }

    // Compute the diff: fields present in input but not in current
    Map<String, Object> diffSource = new LinkedHashMap<>();
    for (Map.Entry<String, Object> entry : inputSource.entrySet()) {
        String fieldName = entry.getKey();
        if ("_source".equals(fieldName)) {
            // Skip _source config to avoid conflict with current index update
            continue;
        }
        if (!currentSource.containsKey(fieldName)) {
            diffSource.put(fieldName, entry.getValue());
        }
    }

    // If there are no new fields, return null to indicate no changes
    if (diffSource.isEmpty()) {
        return null;
    }

    // Build and return a new Mappings object containing only the diff
    Mappings diffMappings = new Mappings();
    diffMappings.setSource(diffSource);
    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings historyMappings) {
    // Retrieve the current index mapping from Elasticsearch
    // (Assuming an Elasticsearch client `esClient` is available in the surrounding class)
    Map<String, Object> currentMapping;
    try {
        currentMapping = esClient.getIndicesClient()
                .getMapping(new GetMappingRequest(tableName))
                .mappings()
                .get(tableName)
                .sourceAsMap();
    } catch (Exception e) {
        // If we cannot retrieve the current mapping, return an empty diff
        return new Mappings(Collections.emptyMap());
    }

    // Extract the property definitions from the history mapping
    Map<String, Object> historyProps = new HashMap<>();
    Object hPropsObj = historyMappings.getMapping().get("properties");
    if (hPropsObj instanceof Map) {
        historyProps.putAll((Map<? extends String, ? extends Object>) hPropsObj);
    }

    // Extract the property definitions from the current mapping
    Map<String, Object> currentProps = new HashMap<>();
    Object cPropsObj = currentMapping.get("properties");
    if (cPropsObj instanceof Map) {
        currentProps.putAll((Map<? extends String, ? extends Object>) cPropsObj);
    }

    // Build the diff: fields present in historyProps but missing in currentProps
    Map<String, Object> diff = new HashMap<>();
    for (Map.Entry<String, Object> entry : historyProps.entrySet()) {
        String field = entry.getKey();
        if ("_source".equals(field)) {
            // Skip the _source config to avoid update conflicts
            continue;
        }
        if (!currentProps.containsKey(field)) {
            diff.put(field, entry.getValue());
        }
    }

    // Return the diff as a new Mappings instance
    return new Mappings(diff);
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        // Retrieve the current mapping for the specified table (index)
        GetMappingsRequest getReq = new GetMappingsRequest();
        getReq.indices(tableName);
        GetMappingsResponse getResp = client.indices().getMapping(getReq, RequestOptions.DEFAULT);

        // Current mapping metadata
        MappingMetaData currentMeta = getResp.mappings().get(tableName);
        Map<String, Object> currentProps = (Map<String, Object>) currentMeta.getSourceAsMap().get("properties");

        // History mapping (input)
        Map<String, Object> historyProps = mappings.getSourceAsMap()
                .entrySet()
                .stream()
                .filter(e -> "properties".equals(e.getKey()))
                .map(Map.Entry::getValue)
                .map(val -> (Map<String, Object>) val)
                .findFirst()
                .orElse(Collections.emptyMap());

        // Build the diff: fields that exist in current mapping but NOT in history mapping
        Map<String, Object> diffProps = new LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
            String fieldName = entry.getKey();
            if ("_source".equals(fieldName)) {
                continue; // skip _source config
            }
            if (!historyProps.containsKey(fieldName)) {
                diffProps.put(fieldName, entry.getValue());
            }
        }

        // If there are no new fields, return an empty Mappings instance
        if (diffProps.isEmpty()) {
            return new Mappings();
        }

        // Construct the diff Mappings object
        Mappings diffMappings = new Mappings();
        Map<String, Object> diffMap = new LinkedHashMap<>();
        diffMap.put("properties", diffProps);
        diffMappings.setSourceAsMap(diffMap);

        return diffMappings;
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute mapping diff for table [" + tableName + "]", e);
    }
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    // Obtain expected mapping structure for the given table (implementation dependent)
    Map<String, Object> expectedMap = buildStructureMapping(tableName);
    if (expectedMap == null) {
        return new Mappings(Collections.emptyMap());
    }

    // Copy history mapping to avoid mutating the original
    Map<String, Object> historyMap = new HashMap<>(mappings.get());
    if (historyMap == null) {
        return new Mappings(expectedMap);
    }

    // Remove _source from both maps to avoid update conflicts
    historyMap.remove("_source");
    Map<String, Object> tempExpected = new HashMap<>(expectedMap);
    tempExpected.remove("_source");

    // Find fields that exist in expected but not in history
    Map<String, Object> diff = new HashMap<>();
    for (Map.Entry<String, Object> entry : tempExpected.entrySet()) {
        if (!historyMap.containsKey(entry.getKey())) {
            diff.put(entry.getKey(), entry.getValue());
        }
    }

    return new Mappings(diff);
}

