public void addNewTarget(Channels channels, IConsumer consumer) {
    if (channels == null || consumer == null) {
        return;
    }
    String target = consumer.getTargetChannel();
    if (target == null || target.isEmpty()) {
        return;
    }
    // Try Channels.addTargetChannel(String)
    try {
        java.lang.reflect.Method m = Channels.class.getMethod("addTargetChannel", String.class);
        m.invoke(channels, target);
        return;
    } catch (Exception ignored) {}
    // Try Channels.add(String)
    try {
        java.lang.reflect.Method m = Channels.class.getMethod("add", String.class);
        m.invoke(channels, target);
        return;
    } catch (Exception ignored) {}
    // Try Channels.add(Object)
    try {
        java.lang.reflect.Method m = Channels.class.getMethod("add", Object.class);
        m.invoke(channels, target);
        return;
    } catch (Exception ignored) {}
    // If Channels implements Collection, add target directly
    if (channels instanceof java.util.Collection) {
        ((java.util.Collection<?>) channels).add(target);
    }
}

