    // Silently drop the event if the buffer is full
    if (!buffer.offer(o)) {
        // buffer full; the event is dropped
    }
}

public void put(LoggingEvent o){
    if (o == null) {
        return;
    }
    // Silently drop the event if the buffer (queue) is full
    this.queue.offer(o);
}

public void put(LoggingEvent o){
    buffer[tail] = o;
    tail = (tail + 1) % buffer.length;
}

public void put(LoggingEvent o){
    // Compute the next write position using circular indexing
    int pos = writeIndex % buffer.length;
    // If the slot is already occupied, the buffer is full – silently drop the event.
    if (buffer[pos] != null) {
        return;
    }
    // Store the event and advance the write index
    buffer[pos] = o;
    writeIndex++;
}

public void put(LoggingEvent o) {
    if (o == null) {
        return;
    }
    // The buffer may be uninitialized or closing
    if (buffer == null) {
        return;
    }
    // If the buffer is full, silently drop the event
    if (count == buffer.length) {
        return;
    }
    // Store the event and advance the write position
    buffer[writePos] = o;
    writePos = (writePos + 1) % buffer.length;
    count++;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = Math.min(end, current + FETCH_DATA_DURATION);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    if (start > end){
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    if (FETCH_DATA_DURATION <= 0){
        throw new IllegalStateException("FETCH_DATA_DURATION must be positive");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end){
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> result = new ArrayList<>();
    if (start >= end) {
        return result;
    }
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long segmentSize = Math.min(remaining, FETCH_DATA_DURATION);
        long next = current + segmentSize;
        result.add(new TimeRange(current, next));
        current = next;
    }
    return result;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    if (start >= end) {
        return timeRanges;
    }
    long current = start;
    while (current < end) {
        long nextEnd = Math.min(current + FETCH_DATA_DURATION, end);
        timeRanges.add(new TimeRange(current, nextEnd));
        current = nextEnd;
    }
    return timeRanges;
}

public static byte[] toPrimitive(final Byte[] array) {
    if (array == null) {
        return null;
    }
    byte[] result = new byte[array.length];
    for (int i = 0; i < array.length; i++) {
        Byte b = array[i];
        if (b == null) {
            throw new NullPointerException("array content is null at index " + i);
        }
        result[i] = b.byteValue();
    }
    return result;
}

