static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the starting day of the bucket
    int startDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reconstruct the date as a long in YYYYMMDD format
    return year * 10000L + month * 100L + startDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    // Extract year, month, and day from the time bucket (format: yyyymmdd)
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day   = timeBucket % 100;

    if (day < 1) {
        // Invalid day; return the original bucket (or handle as needed)
        return timeBucket;
    }

    // Compute the start day of the interval that contains the given day.
    long intervalStartDay = ((day - 1) / dayStep) * dayStep + 1;

    // Reconstruct the compressed bucket
    return year * 10000 + month * 100 + intervalStartDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
