}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int end = index + len;
    int total = 0;
    int i = index;
    while (i < end) {
        int cp = Character.codePointAt(str, i, end);
        if (cp <= 0x7F) {
            total += 1;
        } else if (cp <= 0x7FF) {
            total += 2;
        } else if (cp <= 0xFFFF) {
            total += 3;
        } else {
            total += 4;
        }
        i += Character.charCount(cp);
    }
    return total;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if(str==null||len==0){
        return 0;
    }
    int end = index + len;
    int size = 0;
    for(int i=index; i<end; i++){
        char ch = str.charAt(i);
        if(ch <= 0x7F){
            size += 1;
        }else if(ch <= 0x7FF){
            size += 2;
        }else if(ch >= 0xD800 && ch <= 0xDBFF && i+1 < end){
            char next = str.charAt(i+1);
            if(next >= 0xDC00 && next <= 0xDFFF){
                size += 4;
                i++; // skip low surrogate
            }else{
                size += 3;
            }
        }else{
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    int end = index + len;
    int bytes = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        int cp;
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            cp = Character.toCodePoint(ch, str.charAt(i + 1));
            i++; // skip low surrogate
        } else {
            cp = ch;
        }
        if (cp <= 0x7F) {
            bytes += 1;
        } else if (cp <= 0x7FF) {
            bytes += 2;
        } else if (cp <= 0xFFFF) {
            bytes += 3;
        } else {
            bytes += 4;
        }
        i++;
    }
    return bytes;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size++; // 1 byte
        } else if (c <= 0x7FF) {
            size += 2; // 2 bytes
        } else {
            // check for surrogate pair
            if (Character.isHighSurrogate(c) && (i + 1) < end) {
                char d = str.charAt(i + 1);
                if (Character.isLowSurrogate(d)) {
                    int codePoint = Character.toCodePoint(c, d);
                    size += (codePoint <= 0xFFFF) ? 3 : 4; // 4-byte UTF-8 for supplementary chars
                    i++; // skip low surrogate
                } else {
                    size += 3; // treat lone high surrogate as 3 bytes
                }
            } else if (Character.isLowSurrogate(c)) {
                // lone low surrogate
                size += 3;
            } else {
                size += 3; // BMP characters 0x800..0xFFFF
            }
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size++;
        } else if (ch < 0x800) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if ((i + 1) < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4;
                    i++; // skip low surrogate
                    continue;
                }
            }
            size += 3; // malformed surrogate, count as three bytes
        } else {
            size += 3; // not a surrogate, within 0x800-0xFFFF
        }
    }
    return size;
}

