public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds array length");
        }
    }

    int newPos = pos + byteLength;
    if (newPos > buf.length) {
        int newSize = Math.max(newPos, 2 * buf.length);
        byte[] tmp = new byte[newSize];
        System.arraycopy(buf, 0, tmp, 0, pos);
        buf = tmp;
    }

    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, buf, pos, byteLength);
    } else {
        for (int i = pos; i < newPos; i++) {
            buf[i] = 0;
        }
    }

    pos = newPos;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if(byteLength < 0) throw new IllegalArgumentException("byteLength must be non-negative");
    int oldSize = this.size;
    this.ensureCapacity(oldSize + byteLength);
    if(byteArrayValue == null){
        for(int i = 0; i < byteLength; i++){
            this.byteVector[oldSize + i] = 0;
        }
    } else {
        System.arraycopy(byteArrayValue, byteOffset, this.byteVector, oldSize, byteLength);
    }
    this.size = oldSize + byteLength;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength == 0) {
        return this;
    }
    int end = position + byteLength;
    if (end > buffer.length) {
        int newSize = Math.max(buffer.length * 2, end);
        buffer = java.util.Arrays.copyOf(buffer, newSize);
    }
    if (byteArrayValue == null) {
        for (int i = position; i < end; i++) {
            buffer[i] = 0;
        }
    } else {
        if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("Invalid offset or length");
        }
        System.arraycopy(byteArrayValue, byteOffset, buffer, position, byteLength);
    }
    position = end;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be >= 0");
    }
    int newLen = ptr + byteLength;
    if (buf == null) {
        int cap = Math.max(8, newLen);
        buf = new byte[cap];
    } else if (buf.length < newLen) {
        int cap = Math.max(buf.length * 2, newLen);
        byte[] newBuf = new byte[cap];
        System.arraycopy(buf, 0, newBuf, 0, buf.length);
        buf = newBuf;
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset / byteLength out of bounds");
        }
        System.arraycopy(byteArrayValue, byteOffset, buf, ptr, byteLength);
    } else {
        for (int i = 0; i < byteLength; i++) {
            buf[ptr + i] = 0;
        }
    }
    ptr = newLen;
    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    // Nothing to add
    if(byteLength <= 0) return this;
    // Ensure capacity
    int required = this.length + byteLength;
    if(required > this.array.length){
        int newSize = Math.max(required, this.array.length * 2);
        byte[] newArray = new byte[newSize];
        System.arraycopy(this.array,0,newArray,0,this.length);
        this.array = newArray;
    }
    if(byteArrayValue == null){
        // fill with null (zero) bytes
        for(int i=0;i<byteLength;i++){
            this.array[this.length + i] = 0;
        }
    }else{
        // Optional bounds check
        if(byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length)
            throw new ArrayIndexOutOfBoundsException("byteOffset/byteLength out of bounds");
        System.arraycopy(byteArrayValue,byteOffset,this.array,this.length,byteLength);
    }
    this.length += byteLength;
    return this;
}

