    byte[] utf8Bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
    // Append the encoded bytes to the provided LinkedBuffer
    lb.append(utf8Bytes, 0, utf8Bytes.length);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        return lb;
    }
    final int len = str.length();
    for (int i = 0; i < len; ) {
        int c = str.charAt(i);
        if (c < 0x80) {
            // 1-byte sequence
            session.writeByte((byte) c);
            i++;
        } else if (c < 0x800) {
            // 2-byte sequence
            session.writeByte((byte) (0xC0 | (c >> 6)));
            session.writeByte((byte) (0x80 | (c & 0x3F)));
            i++;
        } else if (Character.isHighSurrogate((char) c) && i + 1 < len && Character.isLowSurrogate(str.charAt(i + 1))) {
            // 4-byte sequence (surrogate pair)
            int codePoint = Character.codePointAt(str, i);
            session.writeByte((byte) (0xF0 | (codePoint >> 18)));
            session.writeByte((byte) (0x80 | ((codePoint >> 12) & 0x3F)));
            session.writeByte((byte) (0x80 | ((codePoint >> 6) & 0x3F)));
            session.writeByte((byte) (0x80 | (codePoint & 0x3F)));
            i += 2;
        } else {
            // 3-byte sequence
            session.writeByte((byte) (0xE0 | (c >> 12)));
            session.writeByte((byte) (0x80 | ((c >> 6) & 0x3F)));
            session.writeByte((byte) (0x80 | (c & 0x3F)));
            i++;
        }
    }
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c < 0x80) {
            lb.put((byte) c);
        } else if (c < 0x800) {
            lb.put((byte) (0xC0 | (c >>> 6)));
            lb.put((byte) (0x80 | (c & 0x3F)));
        } else if (c >= 0xD800 && c <= 0xDBFF && i + 1 < len) {
            char c2 = str.charAt(i + 1);
            if (c2 >= 0xDC00 && c2 <= 0xDFFF) {
                int codePoint = ((c - 0xD800) << 10) + (c2 - 0xDC00) + 0x10000;
                lb.put((byte) (0xF0 | (codePoint >>> 18)));
                lb.put((byte) (0x80 | ((codePoint >>> 12) & 0x3F)));
                lb.put((byte) (0x80 | ((codePoint >>> 6) & 0x3F)));
                lb.put((byte) (0x80 | (codePoint & 0x3F)));
                i++; // skip low surrogate
                continue;
            }
        }
        lb.put((byte) (0xE0 | (c >>> 12)));
        lb.put((byte) (0x80 | ((c >>> 6) & 0x3F)));
        lb.put((byte) (0x80 | (c & 0x3F)));
    }
    return lb;
}

