private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    int start = strLen - suffixLen;
    return str.regionMatches(ignoreCase, start, suffix, 0, suffixLen);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase){
    if(str == null && suffix == null) return true;
    if(str == null || suffix == null) return false;
    if(suffix.length() > str.length()) return false;
    return str.regionMatches(ignoreCase, str.length() - suffix.length(), suffix, 0, suffix.length());
}

private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    if (str == null || suffix == null) {
        return str == null && suffix == null;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (!ignoreCase) {
        return str.endsWith(suffix);
    } else {
        int offset = strLen - suffixLen;
        for (int i = 0; i < suffixLen; i++) {
            char c1 = str.charAt(offset + i);
            char c2 = suffix.charAt(i);
            if (Character.toLowerCase(c1) != Character.toLowerCase(c2)) {
                return false;
            }
        }
        return true;
    }
}

private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase){
    // both null => true, one null => false
    if (str == null) {
        return suffix == null;
    }
    if (suffix == null) {
        return false;
    }
    int strLen = str.length();
    int sufLen = suffix.length();
    if (sufLen > strLen) {
        return false;
    }
    if (!ignoreCase) {
        return str.endsWith(suffix);
    }
    // case-insensitive comparison using regionMatches
    return str.regionMatches(true, strLen - sufLen, suffix, 0, sufLen);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    int suffixLen = suffix.length();
    int strLen = str.length();
    if (suffixLen > strLen) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLen - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    String[] rawSegments = rawPath.split("/", -1);
    int startIdx = 0;
    if (u.isAbsolute() && rawSegments.length > 0 && rawSegments[0].isEmpty()) {
        startIdx = 1; // ignore leading empty segment for absolute paths
    }
    for (int i = startIdx; i < rawSegments.length; i++) {
        String seg = rawSegments[i];
        if (!seg.isEmpty()) {
            if (decode) {
                try {
                    seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
                } catch (Exception e) {
                    // If decoding fails, keep the raw segment
                }
            }
            segments.add(new PathSegmentImpl(seg));
        }
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }
    int start = rawPath.startsWith("/") ? 1 : 0;
    String path = rawPath.substring(start);
    for (String part : path.split("/", -1)) {
        String value = part;
        if (decode) {
            value = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8);
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }

    // Remove leading '/' for absolute paths (if present)
    if (rawPath.startsWith("/")) {
        rawPath = rawPath.substring(1);
    }

    // Split into segments
    String[] parts = rawPath.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String segmentText;
        if (decode) {
            try {
                segmentText = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // Fallback to raw part if decoding fails
                segmentText = part;
            }
        } else {
            segmentText = part;
        }
        // Create a PathSegmentImpl instance
        PathSegmentImpl pathSegment = new PathSegmentImpl(segmentText);
        segments.add(pathSegment);
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> result = new ArrayList<>();
    if (u == null) {
        return result;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return result;
    }
    int start = 0;
    if (path.startsWith("/")) {
        start = 1; // ignore leading slash for absolute paths
    }
    int len = path.length();
    int i = start;
    while (i <= len) {
        int slash = path.indexOf('/', i);
        String segment;
        if (slash == -1) {
            segment = path.substring(i);
            i = len + 1; // exit loop
        } else {
            segment = path.substring(i, slash);
            i = slash + 1;
        }
        String decodedSegment = segment;
        if (decode) {
            try {
                decodedSegment = java.net.URLDecoder.decode(segment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // Fallback: keep original if decoding fails
            }
        }
        result.add(new PathSegmentImpl(decodedSegment));
    }
    return result;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int start = 0;
    // If the path component is absolute, ignore the leading '/'
    if (!u.isOpaque() && path.startsWith("/")) {
        start = 1;
    }
    String remaining = path.substring(start);
    if (remaining.isEmpty()) {
        return segments;
    }
    String[] parts = remaining.split("/", -1); // keep empty segments
    for (String part : parts) {
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, fall back to the original string
                seg = part;
            }
        }
        segments.add(new PathSegmentImpl(seg));
    }
    return segments;
}

