private Logger findLogger(Logger current, String name) {
    if (name.equals(current.getName())) {
        return current;
    }
    try {
        // Attempt to traverse children if the Logger implementation provides one
        Object childrenObj = current.getDeclaredFieldValue("children");
        if (childrenObj instanceof Iterable<?>) {
            for (Object child : (Iterable<?>) childrenObj) {
                if (child instanceof Logger) {
                    Logger found = findLogger((Logger) child, name);
                    if (found != null) {
                        return found;
                    }
                }
            }
        }
    } catch (Exception ignored) {
        // If the Logger doesn't expose children, fall back to query-specific methods
    }
    return null;
}

