private static Logger getRootLogger() {
    try {
        // Prefer Log4j2 API if available
        Class<?> logManagerClass = Class.forName("org.apache.logging.log4j.LogManager");
        Object ctx = logManagerClass.getMethod("getContext", boolean.class).invoke(null, false);
        return (Logger) ctx.getClass().getMethod("getRootLogger").invoke(ctx);
    } catch (Throwable t1) {
        try {
            // Fall back to Log4j 1.x
            Class<?> loggerClass = Class.forName("org.apache.log4j.Logger");
            return (Logger) loggerClass.getMethod("getRootLogger").invoke(null);
        } catch (Throwable t2) {
            return null;
        }
    }
}

