    }
    // Recursively search through all child loggers
    for (Logger child : this.getChildren()) {
        Logger found = child.exists(name);
        if (found != null) {
            return found;
        }
    }
    // No matching logger found
    return null;
}

public Logger exists(String name){
    if(name == null || name.isEmpty()){
        return null;
    }
    // LogManager retains all created loggers; getLogger returns null if none found.
    return LogManager.getLogManager().getLogger(name);
}

