private void pop(final String descriptor) {
    String params = descriptor;
    // If descriptor is a method descriptor, strip the parameter part
    int start = descriptor.indexOf('(');
    if (start >= 0) {
        int end = descriptor.indexOf(')', start);
        if (end < 0) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        params = descriptor.substring(start + 1, end);
    }

    int i = 0;
    while (i < params.length()) {
        char c = params.charAt(i);
        switch (c) {
            case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                // single slot primitive: byte, char, float, int, short, boolean
                stack.pop();
                i++;
                break;
            case 'D': case 'J':
                // double-slot primitives: double, long
                stack.pop();
                stack.pop();
                i++;
                break;
            case 'L':
                // object type: L fully-qualified-class ;
                int semi = params.indexOf(';', i);
                if (semi == -1) {
                    throw new IllegalArgumentException("Invalid object descriptor in: " + descriptor);
                }
                stack.pop(); // pop the object reference
                i = semi + 1;
                break;
            case '[':
                // array type: one slot regardless of dimensions
                i++;
                // Skip any nested array brackets
                while (i < params.length() && params.charAt(i) == '[') {
                    i++;
                }
                // Then skip the component type
                if (i < params.length() && params.charAt(i) == 'L') {
                    int arrSemi = params.indexOf(';', i);
                    if (arrSemi == -1) {
                        throw new IllegalArgumentException("Invalid array descriptor in: " + descriptor);
                    }
                    i = arrSemi + 1;
                } else if (i < params.length()) {
                    // Primitive component
                    i++;
                } else {
                    throw new IllegalArgumentException("Unexpected end of descriptor: " + descriptor);
                }
                stack.pop(); // one slot for the array reference
                break;
            default:
                throw new IllegalArgumentException("Unknown type descriptor character: " + c + " in " + descriptor);
        }
    }
}

