    }
    if (i == j) {
        return; // no need to swap identical indices
    }
    if (i < 0 || i >= arr.length || j < 0 || j >= arr.length) {
        throw new IndexOutOfBoundsException("Index out of bounds: i=" + i + ", j=" + j + ", length=" + arr.length);
