    if (classpath == null || classpath.isEmpty()){
        return new File[0];
    }
    String sep = System.getProperty("path.separator");
    String[] parts = classpath.split(java.util.regex.Pattern.quote(sep));
    java.util.List<File> list = new java.util.ArrayList<>();
    for (String p : parts){
