        return;
    }
    int required = len + size;
    if (required <= buffer.length) return;
    int newCapacity = Math.max(buffer.length << 1, required);
    byte[] newBuf = new byte[newCapacity];
    System.arraycopy(buffer, 0, newBuf, 0, len);
    buffer = newBuf;
}

private void enlarge(final int size){
    // Determine the number of additional bytes that will be added.
    if (size <= 0) {
        return; // no need to enlarge for non-positive size
    }

    int currentCapacity = this.data.length;          // current capacity of the internal byte array
    int usedSize = this.size;                        // current number of bytes stored

    // Compute the new capacity.  We simply add the requested size to the current
    // capacity, but guard against integer overflow.
    int newCapacity = currentCapacity + size;
    if (newCapacity < 0) { // overflow has occurred
        newCapacity = Integer.MAX_VALUE;
    }

    // Allocate a new array with the larger capacity.
    byte[] newData = new byte[newCapacity];

    // Copy over the existing contents.
    System.arraycopy(this.data, 0, newData, 0, usedSize);

    // Replace the old backing array with the new one.
    this.data = newData;
}

private void enlarge(final int size) {
    if (size <= 0) return;
    int oldLen = (bytes == null) ? 0 : bytes.length;
    int newLen = oldLen + size;
    byte[] tmp = new byte[newLen];
    if (bytes != null) {
        System.arraycopy(bytes, 0, tmp, 0, oldLen);
    }
    bytes = tmp;
}

private void enlarge(final int size) {
    // Ensure there is room for 'size' more bytes.
    int minCapacity = pos + size;
    if (minCapacity > buffer.length) {
        int newCapacity = Math.max(buffer.length << 1, minCapacity);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, pos);
        buffer = newBuffer;
    }
}

private void enlarge(final int size) {
    if (size <= 0) return;
    int needed = length + size;
    if (buffer != null && needed <= buffer.length) return;
    int newCap;
    if (buffer == null) {
        newCap = Math.max(1, needed);
    } else {
        newCap = Math.max(buffer.length << 1, needed);
    }
    byte[] newBuffer = new byte[newCap];
    if (buffer != null) {
        System.arraycopy(buffer, 0, newBuffer, 0, length);
    }
    buffer = newBuffer;
}

