private boolean containsAllFields(Fields fields) {
    if (fields == null) {
        return false;
    }
    // If Fields is directly iterable, we can iterate over its elements
    if (fields instanceof java.lang.Iterable<?>) {
        for (Object obj : (java.lang.Iterable<?>) fields) {
            String key = obj.toString();
            if (!properties.containsKey(key)) {
                return false;
            }
        }
        return true;
    }
    // If not directly iterable, try a common accessor method that may return a collection
    try {
        java.lang.reflect.Method method = fields.getClass().getMethod("getFields");
        Object result = method.invoke(fields);
        if (result instanceof java.util.Collection<?>) {
            for (Object obj : (java.util.Collection<?>) result) {
                String key = obj.toString();
                if (!properties.containsKey(key)) {
                    return false;
                }
            }
            return true;
        }
    } catch (Exception e) {
        // ignore reflection failures
    }
    return false;
}

private boolean containsAllFields(Fields fields) {
    if (fields == null) {
        return false;
    }
    for (String fieldName : fields.getFieldNames()) {
        if (!properties.containsKey(fieldName)) {
            return false;
        }
    }
    return true;
}

private boolean containsAllFields(Fields fields) {
    if (fields == null) {
        return false;
    }
    // Assume Fields implements Map<String, ?> or Iterable of keys
    if (fields instanceof java.util.Map) {
        java.util.Map<?, ?> map = (java.util.Map<?, ?>) fields;
        for (Object key : map.keySet()) {
            if (!this.properties.containsKey(key)) {
                return false;
            }
        }
        return true;
    }
    if (fields instanceof java.lang.Iterable) {
        for (Object key : (java.lang.Iterable<?>) fields) {
            if (!this.properties.containsKey(key)) {
                return false;
            }
        }
        return true;
    }
    // If Fields has no obvious iteration contract, we can't determine
    return false;
}

private boolean containsAllFields(Fields fields){
    if (fields == null || fields.isEmpty()){
        return true;
    }
    for (String fieldName : fields){
        if (!properties.containsKey(fieldName)){
