        }
    }
    return true;
}

private boolean containsAllFields(Fields fields) {
    if (fields == null || properties == null) {
        return false;
    }
    for (Object key : fields.keySet()) {
        if (!(key instanceof String)) {
            continue; // skip non-string keys
        }
        if (!properties.containsKey((String) key)) {
            return false;
        }
    }
    return true;
}

