public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Assuming the LinkedBuffer contains a byte array 'data' and an int field 'count' indicating the number of valid bytes.
        out.write(current.data, 0, current.count);
        total += current.count;
        current = current.next;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        // Number of valid bytes in this node
        int len = cur.pos;
        // Write the byte content of the current node
        out.write(cur.buf, 0, len);
        total += len;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer curr = node;
    while (curr != null) {
        int len = curr.size;
        if (len > 0) {
            out.write(curr.data, 0, len);
            totalSize += len;
        }
        curr = curr.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        final byte[] buf = current.buf;
        final int len = current.count;
        out.write(buf, 0, len);
        total += len;
        current = current.next;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        // 'off' represents the number of bytes written into this buffer,
        // i.e., the data occupies buf[0, off).
        int len = node.off;
        if (len > 0) {
            out.write(node.buf, 0, len);
            totalSize += len;
        }
        node = node.next;
    }
    return totalSize;
}

