    String levelStr = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
    String threadStr = event.getThreadName() != null ? event.getThreadName() : "unknownThread";
    String loggerName = event.getLoggerName() != null ? event.getLoggerName() : "unknownLogger";
