    StringBuilder sb = new StringBuilder();
    sb.append(dateStr)
      .append(" [")
      .append(levelStr)
      .append("] (")
      .append(threadStr)
      .append(") ")
      .append(loggerName)
      .append(" - ")
      .append(message);

    // Include stack trace if present
    Throwable t = null;
    try {
        ThrowableProxy tp = event.getThrowableProxy();
        if (tp != null) {
            t = tp.getThrowable();
        }
    } catch (NoSuchMethodError | IllegalArgumentException e) {
        // Method not present; skip throwable
    }
    if (t == null) {
        try {
            t = event.getThrowable();
        } catch (NoSuchMethodError | IllegalArgumentException ignored) {}
    }
    if (t != null) {
        sb.append(System.lineSeparator());
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        t.printStackTrace(pw);
        pw.flush();
        sb.append(sw.toString());
    }

    return sb.toString();
}

