private void putAbstractTypes(final int start, final int end){
    for (int i = start; i < end; i++) {
        // Convert the abstract type stored in currentFrame to the JVMS verification_type_info format
        VerificationTypeInfo info = currentFrame[i].toVerificationTypeInfo();
        stackMapTableEntries.add(info);
    }
}

private void putAbstractTypes(final int start,final int end){
    // Iterate over the abstract types stored in currentFrame between start (inclusive)
    // and end (exclusive) and write their verification_type_info representation
    // into the stackMapTableEntries buffer.
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        // Write the tag for the abstract type
        stackMapTableEntries.writeByte(type.getTag());
        // For OBJECT and UNINITIALIZED types, write the additional 2‑byte info
        if (type.getTag() == 7) {                // ITEM_Object
            stackMapTableEntries.writeUnsignedShort(type.getClassIndex());
        } else if (type.getTag() == 8) {           // ITEM_Uninitialized
            stackMapTableEntries.writeUnsignedShort(type.getOffset());
        }
    }
}

private void putAbstractTypes(final int start,final int end){
    for (int i = start; i < end; i++) {
        final Object type = currentFrame[i];
        if (type instanceof String) {
            // ITEM_Object tag = 7
            stackMapTableEntries.putByte(7);
            stackMapTableEntries.putUTF((String) type);
        } else if (type instanceof Integer) {
            // Verification type tags 0-6
            stackMapTableEntries.putByte((Integer) type);
        } else {
            throw new IllegalStateException("Unsupported verification type: " + type);
