        throw new IllegalStateException("Specified distribution path is not a directory: " + distPath);
    }

    // Store the validated distribution directory for later use
    this.distDir = distDir;
}

public void init() {
    // Define default distribution path
    String distPath = "dist";
    // Try to load from environment variable or system property
    String envPath = System.getenv("DIST_PATH");
    if (envPath != null && !envPath.isEmpty()) {
        distPath = envPath;
    } else {
        String sysProp = System.getProperty("dist.path");
        if (sysProp != null && !sysProp.isEmpty()) {
            distPath = sysProp;
        }
    }

    java.io.File distDir = new java.io.File(distPath);
    if (!distDir.exists()) {
        boolean created = distDir.mkdirs();
        if (!created) {
            System.err.println("Failed to create distribution directory: " + distPath);
        } else {
            System.out.println("Created distribution directory: " + distPath);
        }
    } else if (!distDir.isDirectory()) {
        System.err.println("Specified dist path is not a directory: " + distPath);
    } else {
        System.out.println("Distribution directory already exists: " + distPath);
    }
}

@Override public String readString() throws IOException {
    int len = readInt();
    if (len < 0) {
        return null;
    }
    if (len == 0) {
        return "";
    }
    byte[] bytes = new byte[len];
    readFully(bytes, 0, len);
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

@Override
public String readString() throws IOException {
    // Read the length prefix of the string. A negative length indicates a null string.
    int length = readInt();
    if (length == -1) {
        return null;
    }
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }

    // Read exactly `length` bytes from the underlying input stream.
    byte[] buffer = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = in.read(buffer, offset, length - offset);
        if (read == -1) {
            throw new EOFException("Unexpected end of input while reading string");
        }
        offset += read;
    }

    // Convert the byte array to a UTF-8 string.
    return new String(buffer, java.nio.charset.StandardCharsets.UTF_8);
}

