private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new HashMap<>();
    if(jsonObject==null) return result;
    for(Map.Entry<String,JsonElement> entry: jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement elem = entry.getValue();
        if("ats".equals(key)){
            if(elem!=null && elem.isJsonPrimitive() && elem.getAsJsonPrimitive().isNumber()){
                result.put(key, elem.getAsNumber().longValue());
            } else {
                result.put(key, elem!=null?elem.toString():null);
            }
        } else if(elem!=null && elem.isJsonPrimitive()){
            JsonPrimitive prim = elem.getAsJsonPrimitive();
            if(prim.isString()){
                result.put(key, prim.getAsString());
            } else if(prim.isNumber()){
                result.put(key, prim.getAsNumber());
            } else if(prim.isBoolean()){
                result.put(key, prim.getAsBoolean());
            } else {
                result.put(key, null);
            }
        } else if(elem!=null && elem.isJsonObject()){
            result.put(key, buildContent(elem.getAsJsonObject()));
        } else if(elem!=null && elem.isJsonArray()){
            List<Object> list = new ArrayList<>();
            for(JsonElement e: elem.getAsJsonArray()){
                if(e!=null && e.isJsonPrimitive()){
                    JsonPrimitive p = e.getAsJsonPrimitive();
                    if(p.isString()){
                        list.add(p.getAsString());
                    } else if(p.isNumber()){
                        list.add(p.getAsNumber());
                    } else if(p.isBoolean()){
                        list.add(p.getAsBoolean());
                    } else {
                        list.add(null);
                    }
                } else if(e!=null && e.isJsonObject()){
                    list.add(buildContent(e.getAsJsonObject()));
                } else {
                    list.add(null);
                }
            }
            result.put(key, list);
        } else {
            result.put(key, null);
        }
    }
    return result;
}

private Map<String,Object> buildContent(JsonObject jsonObject) {
    Map<String,Object> result = new HashMap<>();
    for (Map.Entry<String,JsonElement> entry : jsonObject.entrySet()) {
        String key = entry.getKey();
        JsonElement element = entry.getValue();
        if (element == null) {
            result.put(key, null);
            continue;
        }
        if (element.isJsonPrimitive()) {
            JsonPrimitive prim = element.getAsJsonPrimitive();
            if (prim.isBoolean()) {
                result.put(key, prim.getAsBoolean());
            } else if (prim.isNumber()) {
                result.put(key, prim.getAsNumber());
            } else if (prim.isString()) {
                result.put(key, prim.getAsString());
            }
        } else if (element.isJsonNull()) {
            result.put(key, null);
        } else {
            // For JsonObject or JsonArray, store the JsonElement itself
            result.put(key, element);
        }
    }
    if (jsonObject.has("ats")) {
        result.put("ats", jsonObject.get("ats"));
    }
    return result;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new LinkedHashMap<>();
    if (jsonObject == null) {
        return content;
    }
    for (Map.Entry<String,JsonElement> entry : jsonObject.entrySet()) {
        String key = entry.getKey();
        JsonElement value = entry.getValue();
        Object obj = null;
        if (value.isJsonPrimitive()) {
            JsonPrimitive prim = value.getAsJsonPrimitive();
            if (prim.isString()) {
                obj = prim.getAsString();
            } else if (prim.isNumber()) {
                obj = prim.getAsNumber();
            } else if (prim.isBoolean()) {
                obj = prim.getAsBoolean();
            }
        } else if (value.isJsonObject()) {
            obj = buildContent(value.getAsJsonObject());
        } else if (value.isJsonArray()) {
            JsonArray arr = value.getAsJsonArray();
            List<Object> list = new ArrayList<>();
            for (JsonElement e : arr) {
                if (e.isJsonPrimitive()) {
                    JsonPrimitive prim = e.getAsJsonPrimitive();
                    if (prim.isString()) {
                        list.add(prim.getAsString());
                    } else if (prim.isNumber()) {
                        list.add(prim.getAsNumber());
                    } else if (prim.isBoolean()) {
                        list.add(prim.getAsBoolean());
                    }
                } else {
                    list.add(buildContent(e.getAsJsonObject()));
                }
            }
            obj = list;
        }
        content.put(key, obj);
    }
    if (jsonObject.has("ats")) {
        content.put("ats", jsonObject.get("ats").getAsString());
    }
    return content;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new HashMap<>();
    if(jsonObject == null){
        return result;
    }
    for(String key : jsonObject.keySet()){
        JsonValue value = jsonObject.get(key);
        Object obj;
        if(value instanceof JsonString){
            obj = ((JsonString) value).getString();
        } else if(value instanceof JsonNumber){
            JsonNumber num = (JsonNumber) value;
            obj = num.isIntegral() ? num.longValue() : num.doubleValue();
        } else if(value instanceof JsonObject){
            obj = buildContent((JsonObject) value);
        } else if(value instanceof JsonArray){
            JsonArray array = (JsonArray) value;
            List<Object> list = new ArrayList<>();
            for(JsonValue v : array){
                if(v instanceof JsonString){
                    list.add(((JsonString)v).getString());
                } else if(v instanceof JsonNumber){
                    JsonNumber num = (JsonNumber) v;
                    list.add(num.isIntegral() ? num.longValue() : num.doubleValue());
                } else if(v instanceof JsonObject){
                    list.add(buildContent((JsonObject)v));
                } else{
                    list.add(v.toString());
                }
            }
            obj = list;
        } else{
            obj = value.toString();
        }
        result.put(key, obj);
    }
    return result;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> contentMap = new HashMap<>();
    if(jsonObject == null) return contentMap;
    if(jsonObject.has("ats") && !jsonObject.get("ats").isJsonNull()){
        JsonElement atsElement = jsonObject.get("ats");
        if(atsElement.isJsonPrimitive()){
            contentMap.put("ats", atsElement.getAsString());
        } else if(atsElement.isJsonArray()){
            List<String> atsList = new ArrayList<>();
            for(JsonElement el : atsElement.getAsJsonArray()){
                atsList.add(el.isJsonPrimitive()?el.getAsString():el.toString());
            }
            contentMap.put("ats", atsList);
        } else if(atsElement.isJsonObject()){
            contentMap.put("ats", atsElement.getAsJsonObject());
        } else {
            contentMap.put("ats", atsElement.toString());
        }
    }
    // copy other properties
    for(Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        if("ats".equals(key)) continue;
        JsonElement el = entry.getValue();
        if(el == null || el.isJsonNull()){
            contentMap.put(key, null);
        } else if(el.isJsonPrimitive()){
            contentMap.put(key, el.getAsString());
        } else if(el.isJsonObject()){
            contentMap.put(key, el.getAsJsonObject());
        } else if(el.isJsonArray()){
            contentMap.put(key, el.getAsJsonArray());
        } else {
            contentMap.put(key, el.toString());
        }
    }
    return contentMap;
}

