public final byte[] toByteArray(){
    int totalSize = 0;
    for (ByteArrayOutputStream segment : buffers) {
        totalSize += segment.size();
    }
    byte[] result = new byte[totalSize];
    int offset = 0;
    for (ByteArrayOutputStream segment : buffers) {
        byte[] data = segment.toByteArray();
        System.arraycopy(data, 0, result, offset, data.length);
        offset += data.length;
    }
    return result;
}

public final byte[] toByteArray() {
    if (bufferList == null || bufferList.isEmpty()) {
        return new byte[0];
    }
    int totalSize = 0;
    for (ByteArrayOutputStream baos : bufferList) {
        totalSize += baos.size();
    }
    byte[] combined = new byte[totalSize];
    int pos = 0;
    for (ByteArrayOutputStream baos : bufferList) {
        byte[] part = baos.toByteArray();
        System.arraycopy(part, 0, combined, pos, part.length);
        pos += part.length;
    }
    return combined;
}

public final byte[] toByteArray() {
    // compute the total number of bytes in all buffers
    int total = 0;
    for (ByteBuffer buf : buffers) {
        total += buf.remaining();
    }
    // if there are no bytes, return an empty array
    if (total == 0) {
        return new byte[0];
    }
    // allocate result array
    byte[] result = new byte[total];
    int position = 0;
    // copy data from each buffer
    for (ByteBuffer buf : buffers) {
        int len = buf.remaining();
        buf.get(result, position, len);
        position += len;
    }
    return result;
}

public final byte[] toByteArray() {
    // Compute the total size of all written buffers
    int totalSize = 0;
    for (ByteBuffer buf : buffers) {
        totalSize += buf.remaining();
    }

    // Allocate the result array
    byte[] result = new byte[totalSize];

    // Copy each buffer's content into the result array
    int offset = 0;
    for (ByteBuffer buf : buffers) {
        int len = buf.remaining();
        buf.get(result, offset, len);
        offset += len;
    }

    return result;
}

