                sb.append('\r');
                i += 2;
                break;
            case '\'':
                sb.append('\'');
                i += 2;
                break;
            case '\"':
                sb.append('\"');
                i += 2;
                break;
            case 'u':
                if (i + 5 >= len) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int codePoint = Integer.parseInt(hex, 16);
                    sb.append((char) codePoint);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence '\\u" + hex + "' at position " + i, e);
                }
                i += 6;
                break;
            default:
                // Check for octal escape (up to 3 octal digits 0-7)
                if (next >= '0' && next <= '7') {
                    int start = i + 1;
                    int end = start;
                    while (end < len && end - start < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                        end++;
                    }
                    String oct = str.substring(start, end);
                    try {
                        int octVal = Integer.parseInt(oct, 8);
                        sb.append((char) octVal);
                    } catch (NumberFormatException e) {
                        // Treat as literal if not a valid octal value
                        sb.append('\\').append(next);
                        // skip only the backslash and the first digit
                        i = start;
                        continue;
                    }
                    i = end;
                } else {
                    // Unknown escape: keep the backslash and the following character
                    sb.append('\\').append(next);
                    i += 2;
                }
                break;
        }
    }
    return sb.toString();
}

