private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }
    Set<V> result = new HashSet<>(Math.min(set1.size(), set2.size()));
    if (set1.size() <= set2.size()) {
        for (V v : set1) {
            if (set2.contains(v)) {
                result.add(v);
            }
        }
    } else {
        for (V v : set2) {
            if (set1.contains(v)) {
                result.add(v);
            }
        }
    }
    return result;
}

