    // If the root is null, nothing to do
    if (root == null) {
        return 0;
    }

    // If the root itself is inactive, remove the entire tree
    if (!root.isActive()) {
        int removedCount = 1 + countAllDescendants(root);
        root = null;
        return removedCount;
    }

