 * Recursively removes inactive nodes under the given node.
 *
 * @param node the parent node whose children are processed
 * @return the number of nodes removed from this subtree
 */
private int removeInactiveRecursively(Category node) {
    int removed = 0;
    List<Category> children = node.getChildren();
    Iterator<Category> it = children.iterator();

    while (it.hasNext()) {
        Category child = it.next();
        if (!child.isActive()) {
            // Remove the entire subtree rooted at this child
            it.remove();
            removed += 1 + countAllDescendants(child);
        } else {
            // Continue searching deeper
            removed += removeInactiveRecursively(child);
        }
    }
    return removed;
}

/**
 * Counts all nodes in the subtree rooted at the specified node
 * (including the node itself).
 *
 * @param node the root of the subtree to count
 * @return the total number of nodes in the subtree
 */
private int countAllDescendants(Category node) {
    int count = 0;
    for (Category child : node.getChildren()) {
        count += 1 + countAllDescendants(child);
    }
    return count;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    List<Category> children = this.getChildren();
    if (children == null) {
        return 0;
    }
    Iterator<Category> iterator = children.iterator();
    while (iterator.hasNext()) {
        Category child = iterator.next();
        if (!child.isActive()) {
            iterator.remove();
            removedCount += 1 + child.removeUnusedNodes();
        } else {
            removedCount += child.removeUnusedNodes();
        }
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int[] removed = {0};
    if (prune(root, removed)) {
        // If the root itself is inactive and has no active descendants, clear the tree
        root = null;
    }
    return removed[0];
}

private boolean prune(Category node, int[] removed) {
    java.util.Iterator<Category> it = node.children.iterator();
    while (it.hasNext()) {
        Category child = it.next();
        if (prune(child, removed)) {
            it.remove();
            removed[0]++;
        }
    }
    return !node.isActive() && node.children.isEmpty();
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    if (root == null) return removedCount;
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        List<Category> children = current.getChildren();
        if (children == null) continue;
        Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                removedCount += 1 + countDescendants(child);
            } else {
                stack.push(child);
            }
        }
    }
    return removedCount;
}

private int countDescendants(Category node) {
    int count = 1;
    for (Category child : node.getChildren()) {
        count += countDescendants(child);
    }
    return count;
}

