final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer){
    // Obtain the offset of the CONSTANT_Utf8 entry in the class file byte array.
    // It is assumed that constantPoolItemIndex[constantPoolEntryIndex] contains this offset.
    int entryOffset = constantPoolItemIndex[constantPoolEntryIndex];
    if (entryOffset < 0 || entryOffset + 3 >= classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
    }

    // The first byte of the entry is the tag (0x01 for CONSTANT_Utf8). Skip it.
    // The next two bytes are the length of the UTF‑8 byte sequence (big‑endian).
    int length = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8) |
                 (classFileBuffer[entryOffset + 2] & 0xFF);

    // Bounds check for the length.
    int bytesStart = entryOffset + 3;
    if (bytesStart + length > classFileBuffer.length) {
        throw new IllegalArgumentException("UTF‑8 length exceeds class file data.");
    }

    // Decode the UTF‑8 bytes into a String using the standard charset.
    String utf8String = new String(
        classFileBuffer,
        bytesStart,
        length,
        java.nio.charset.StandardCharsets.UTF_8
    );

    // Copy the decoded characters into the supplied buffer.
    char[] decodedChars = utf8String.toCharArray();
    if (charBuffer.length < decodedChars.length) {
        throw new IllegalArgumentException(
            "Provided char buffer is too small for the UTF‑8 string (requires "
            + decodedChars.length + " chars)."
        );
    }
    System.arraycopy(decodedChars, 0, charBuffer, 0, decodedChars.length);

    return utf8String;
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Find byte offset of the CONSTANT_Utf8 entry
    int entryOffset = getCpEntryOffset(constantPoolEntryIndex);
    // The first two bytes of the entry specify the length of the UTF-8 byte sequence
    int length = ((classFileBuffer[entryOffset] & 0xFF) << 8)
               | (classFileBuffer[entryOffset + 1] & 0xFF);
    // Read up to the available buffer space
    int limit = Math.min(length, charBuffer.length);
    for (int i = 0; i < limit; i++) {
        // Each UTF-8 byte is converted to a char; the actual mapping is delegated to a helper
        charBuffer[i] = decodeUtf8Byte(classFileBuffer[entryOffset + 2 + i]);
    }
    return new String(charBuffer, 0, limit);
}

final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    int offset = 10; // start after magic, version and constant_pool_count (4+2+2)
    for (int i=1; i<constantPoolEntryIndex; i++){
        int tag = classFileBuffer[offset] & 0xFF;
        offset++;
        switch(tag){
            case 1: { // CONSTANT_Utf8
                int len = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
                offset += 2 + len;
                break;
            }
            case 3: // CONSTANT_Integer
            case 4: // CONSTANT_Float
                offset += 4;
                break;
            case 5: // CONSTANT_Long
            case 6: // CONSTANT_Double
                offset += 8;
                i++; // these occupy two places
                break;
            case 7: // CONSTANT_Class
            case 8: // CONSTANT_String
                offset += 2;
                break;
            case 9: // CONSTANT_Fieldref
            case 10: // CONSTANT_Methodref
            case 11: // CONSTANT_InterfaceMethodref
                offset += 4;
                break;
            case 12: // CONSTANT_NameAndType
                offset += 4;
                break;
            default:
                throw new IllegalArgumentException("Unknown constant pool tag "+tag+" at index "+i);
        }
    }
    int tag = classFileBuffer[offset] & 0xFF;
    if (tag != 1){
        throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index "+constantPoolEntryIndex+" but found tag "+tag);
    }
    offset++;
    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset+1] & 0xFF);
    offset += 2;
    int readBytes = 0, outPos = 0;
    while (readBytes < length){
        int b = classFileBuffer[offset++] & 0xFF;
        readBytes++;
        if ((b & 0x80) == 0){
            charBuffer[outPos++] = (char)b;
        } else if ((b & 0xE0) == 0xC0){
            int b2 = classFileBuffer[offset++] & 0xFF;
            readBytes++;
            charBuffer[outPos++] = (char)(((b & 0x1F) << 6) | (b2 & 0x3F));
        } else {
            int b2 = classFileBuffer[offset++] & 0xFF;
            int b3 = classFileBuffer[offset++] & 0xFF;
            readBytes += 2;
            charBuffer[outPos++] = (char)(((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
        }
    }
    return new String(charBuffer, 0, outPos);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Guard against invalid index
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPoolInfoOffsets.length) {
        return null;
    }

    // The offset in the byte array where the CONSTANT_Utf8 entry starts.
    // The entry layout is: [tag][length(2 bytes)][bytes...]
    final int entryOffset = constantPoolInfoOffsets[constantPoolEntryIndex];

    // Read the length of the UTF-8 bytes (2 bytes big-endian)
    final int len = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8)
                  | (classFileBuffer[entryOffset + 2] & 0xFF);

    // Ensure the caller has supplied a buffer large enough
    if (len > charBuffer.length) {
        throw new IllegalArgumentException("Provided char buffer is too small");
    }

    // Convert each byte to a char (this assumes the UTF-8 data contains only single-byte characters)
    // For a full UTF-8 decoding, a CharsetDecoder would be required.
    for (int i = 0; i < len; i++) {
        charBuffer[i] = (char) (classFileBuffer[entryOffset + 3 + i] & 0xFF);
    }

    return new String(charBuffer, 0, len);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Resolve the start offset of the constant pool entry.
    // It is assumed that the class maintains an array containing the
    // absolute byte offset of each constant pool entry in the class file.
    int entryOffset = constantPoolEntryOffsets[constantPoolEntryIndex];
    // The first byte at entryOffset is the tag (CONSTANT_Utf8 = 1).
    // The next two bytes give the length of the UTF‑8 string.
    int len = ((classFileBuffer[entryOffset + 1] & 0xFF) << 8)
            | (classFileBuffer[entryOffset + 2] & 0xFF);
    // Create the string using a platform default charset; the caller
    // is expected to use the returned string rather than rely on
    // the charset, but we also copy the characters into the provided buffer.
    String str = new String(classFileBuffer, entryOffset + 3, len);
    int chars = str.length();
    System.arraycopy(str.toCharArray(), 0, charBuffer, 0, chars);
    return str;
}

