private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start);
    while (true) {
        Node current = circ.getNode();
        if (predicate.test(current)) {
            return circ;
        }
        if (current.equals(stop)) {
            return circ;
        }
        circ = (dir > 0) ? circ.next() : circ.prev();
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Construct a circulator starting at the supplied node and in the given direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the starting node already satisfies the predicate, return it immediately.
    if (predicate.test(circ.node())) {
        return circ;
    }

    // Traverse the outer face until we either meet the stop node or find a node that satisfies
    // the predicate. We keep rotating the circulator using `next()` (forward movement in the
    // specified direction). If the circulator ever returns to the start node we stop to
    // avoid infinite loops in degenerate graphs.
    while (true) {
        circ.next();                      // move to the next node on the face
        Node current = circ.node();       // obtain the node the circulator is at now

        // Stop if we've reached the node that marks the end of the search.
        if (current == stop) {
            break;
        }

        // Stop if the predicate is satisfied.
        if (predicate.test(current)) {
            break;
        }

        // Safety check: if we loop back to the starting node, break out to avoid an infinite loop.
        if (current == start) {
            break;
        }
    }

    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator starting at the given node and moving in the specified direction.
    OuterFaceCirculator it = new OuterFaceCirculator(start, dir);

    // Walk around the outer face until we hit the stop node or find a node that satisfies the predicate.
    while (!it.getNode().equals(stop)) {
        if (predicate.test(it.getNode())) {
            return it;                // Found a suitable node.
        }
        it = it.next();                 // Move to the next node around the outer face.
    }

    // If the loop exited, we have reached the stop node.
    return it;                            // Return a circulator pointing at the stop node.
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // If the start and stop nodes coincide, simply return a circulator pointing to stop.
    if (Objects.equals(start, stop)) {
        return new OuterFaceCirculator(stop, dir);
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = circ.get();
    while (!Objects.equals(current, stop) && !predicate.test(current)) {
        circ = circ.next();
        current = circ.get();
    }

    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (start == null || stop == null) {
        return null;
    }
    OuterFaceCirculator cur = new OuterFaceCirculator(start, dir);
    if (predicate.test(cur.node())) {
        return cur;
    }
    while (!cur.node().equals(stop)) {
        cur = cur.next();
        if (cur == null) {
            break; // safeguard against malformed circulator
        }
        if (predicate.test(cur.node())) {
            return cur;
        }
    }
    // If we reach here, either the predicate never matched or we stopped at 'stop'.
    return new OuterFaceCirculator(stop, dir);
}

