public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength){
    if (byteLength == 0) {
        return this;
    }
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    int newSize = this.size + byteLength;
    if (newSize > this.bytes.length) {
        int newCapacity = Math.max(this.bytes.length * 2, newSize);
        this.bytes = java.util.Arrays.copyOf(this.bytes, newCapacity);
    }
    if (byteArrayValue == null) {
        java.util.Arrays.fill(this.bytes, this.size, newSize, (byte)0);
    } else {
        java.lang.System.arraycopy(byteArrayValue, byteOffset, this.bytes, this.size, byteLength);
    }
    this.size = newSize;
    return this;
}

