public final MatchResult match(CharSequence uri){
    if (uri == null) return null;
    String uriStr = uri.toString();
    if (uriStr.isEmpty()) return null;
    if (uriStr.charAt(0) == '/') {
        uriStr = uriStr.substring(1);
    }
    if (this.pattern == null || this.pattern.isEmpty()) {
        return null;
    }
    String patternStr = this.pattern;
    if (patternStr.charAt(0) == '/') {
        patternStr = patternStr.substring(1);
    }
    java.util.StringTokenizer pt = new java.util.StringTokenizer(patternStr, "/");
    java.util.StringTokenizer ut = new java.util.StringTokenizer(uriStr, "/");
    java.util.Map<String, String> params = new java.util.HashMap<>();
    while (pt.hasMoreTokens()) {
        if (!ut.hasMoreTokens()) {
            return null; // URI has fewer parts than the pattern
        }
        String p = pt.nextToken();
        String u = ut.nextToken();
        if (p.startsWith("{") && p.endsWith("}")) {
            String name = p.substring(1, p.length() - 1);
            params.put(name, u);
        } else if (p.startsWith(":")) {
            String name = p.substring(1);
            params.put(name, u);
        } else {
            if (!p.equals(u)) {
                return null; // segment mismatch
            }
        }
    }
    if (ut.hasMoreTokens()) {
        return null; // URI has more parts than the pattern
    }
    return new MatchResult(params);
}

public final MatchResult match(CharSequence uri) {
    if (uri == null) {
        return null;
    }
    java.util.regex.Pattern pat = this.pattern;
    if (pat == null) {
        return null;
    }
    java.util.regex.Matcher m = pat.matcher(uri);
    if (!m.matches()) {
        return null;
    }
    int groupCount = m.groupCount();
    String[] matchedGroups = new String[groupCount];
    for (int i = 1; i <= groupCount; i++) {
        matchedGroups[i - 1] = m.group(i);
    }
    return new MatchResult(uri.toString(), matchedGroups);
}

