    }
    int min = java.lang.Integer.MAX_VALUE;
    int max = java.lang.Integer.MIN_VALUE;
    java.util.Set<Integer> unique = new java.util.HashSet<>();
    for (Integer idx : indices) {
        if (!unique.add(idx)) {
            continue; // skip duplicates
        }
        if (idx < min) {
            min = idx;
        }
        if (idx > max) {
            max = idx;
        }
    }
    int expectedCount = max - min + 1;
    if (unique.size() != expectedCount) {
        throw new IllegalStateException(
            "Sharding key indices for model '" + modelName +
            "' are not continuous. Indices: " + unique);
    }
}

