    if (r == null) {
        return Action.CONTINUE;
    }
    try {
        // Only suspend the resource for transport types that support suspension.
        switch (r.getTransport()) {
            case XHR:
            case XHR_STREAMING:
            case WEBSOCKET:
            case EVENT_SOURCE:
                r.suspend();
                break;
            default:
                // No suspension needed for unsupported transports
