    // Automatically suspend the resource unless it is a simple GET/HEAD request
    // which is usually used for initial HTTP negotiations (e.g., long polling).
    if (!r.isSuspended()) {
        String transport = r.getTransport();
        if (transport == null) {
            // Fallback: check the HTTP method of the request.
            String method = r.getRequest().getMethod();
            if (!"GET".equalsIgnoreCase(method) && !"HEAD".equalsIgnoreCase(method)) {
                r.suspend();
            }
        } else {
            // Suspend for any transport other than raw GET/HEAD
            if (!"GET".equalsIgnoreCase(transport) && !"HEAD".equalsIgnoreCase(transport)) {
                r.suspend();
            }
        }
    }
    return Action.CONTINUE;
}

