@Override
public boolean containsKey(final Object key) {
    if (key == null) {
        // Search for a node that stores a null key
        for (Node<?> entry : table) {
            Node<?> e = entry;
            while (e != null) {
                if (e.key == null) {
                    return true;
                }
                e = e.next;
            }
        }
        return false;
    }
    int hash = hash(key);
    int index = (table.length - 1) & hash;
    Node<?> e = table[index];
    while (e != null) {
        if (e.hash == hash && e.key.equals(key)) {
            return true;
        }
        e = e.next;
    }
    return false;
}

