protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    // Copy of the set to keep track of remaining edges
    Set<E> remaining = new HashSet<>(tour);
    if (remaining.isEmpty()) {
        return new DefaultGraphPath<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }

    // Lists for vertices and edges in the path
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();

    // Start with any edge
    E firstEdge = remaining.iterator().next();
    remaining.remove(firstEdge);
    V start = graph.getEdgeSource(firstEdge);
    V end = graph.getEdgeTarget(firstEdge);
    vertexList.add(start);
    vertexList.add(end);
    edgeList.add(firstEdge);
    double totalWeight = graph.getEdgeWeight(firstEdge);

    V lastVertex = end;

    // Build the tour by following edges
    while (!remaining.isEmpty()) {
        boolean found = false;
        for (E e : new ArrayList<>(remaining)) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(lastVertex) || tgt.equals(lastVertex)) {
                remaining.remove(e);
                edgeList.add(e);
                totalWeight += graph.getEdgeWeight(e);
                // Append the other vertex of the edge to the path
                V nextVertex = src.equals(lastVertex) ? tgt : src;
                vertexList.add(nextVertex);
                lastVertex = nextVertex;
                found = true;
                break;
            }
        }
        if (!found) {
            // No connecting edge found; break to avoid infinite loop
            break;
        }
    }

    // Construct and return the DefaultGraphPath
    return new DefaultGraphPath<>(graph, vertexList, edgeList, totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    // Map each vertex to the list of incident edges in the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }
    // Find a starting vertex (prefer a vertex of degree 1, otherwise arbitrary)
    V start = null;
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        // All vertices are of degree 2 (cycle), choose any
        start = adjacency.keySet().iterator().next();
    }
    // Construct the ordered list of vertices and edges
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();
    V current = start;
    vertices.add(current);
    while (usedEdges.size() < tour.size()) {
        List<E> adjEdges = adjacency.get(current);
        E nextEdge = null;
        for (E e : adjEdges) {
            if (!usedEdges.contains(e)) {
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null) {
            // No unused edge found – tour may be disconnected
            break;
        }
        vertices.add(graph.getEdgeSource(nextEdge).equals(current) ?
                    graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge));
        edges.add(nextEdge);
        usedEdges.add(nextEdge);
        current = vertices.get(vertices.size() - 1);
    }
    return new GraphPathImpl<>(graph, vertices, edges);
}

