        return null;
    }

    // Build adjacency map for vertices in the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
    }

    // Pick any vertex from the tour as the starting point
    V start = adjacency.keySet().iterator().next();
    List<E> edgeList = new ArrayList<>();
    List<V> vertexList = new ArrayList<>();
    vertexList.add(start);
    V current = start;
    E prevEdge = null;

    // Traverse the cycle until all edges are visited
    while (edgeList.size() < tour.size()) {
        List<E> candidates = adjacency.get(current);
        E nextEdge = null;
        for (E candidate : candidates) {
            if (candidate.equals(prevEdge)) {
                continue;
            }
            if (!edgeList.contains(candidate)) {
                nextEdge = candidate;
                break;
            }
        }

        if (nextEdge == null) {
            // No unvisited edge found – the input set may not form a proper tour
            break;
        }

        edgeList.add(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge);
        if (nextVertex.equals(current)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        }
        vertexList.add(nextVertex);
        prevEdge = nextEdge;
        current = nextVertex;
    }

    // The last vertex should be the same as the start for a cycle
    // If we didn't close the cycle, add the start vertex to complete the path
    if (!vertexList.get(vertexList.size() - 1).equals(start)) {
        vertexList.add(start);
    }

    // Construct and return the GraphPath
    return new GraphPathImpl<>(graph, start, current, edgeList);
}

