protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    if (tour == null || graph == null || tour.isEmpty()) {
        return null;
    }
    // Build adjacency list for all vertices in the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(tgt, k -> new ArrayList<>()).add(e);
    }
    // Find a start vertex: prefer one with degree 1 for a path, otherwise any vertex
    V start = null;
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (!graph.getType().isDirected() && entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null) {
        start = adjacency.keySet().iterator().next();
    }
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    vertexList.add(current);
    // Traverse edges to build the path
    while (visited.size() < tour.size()) {
        List<E> candidates = new ArrayList<>();
        List<E> edgesFromCurrent = adjacency.getOrDefault(current, Collections.emptyList());
        if (graph.getType().isDirected()) {
            for (E e : edgesFromCurrent) {
                if (!visited.contains(e) && graph.getEdgeSource(e).equals(current)) {
                    candidates.add(e);
                }
            }
        } else {
            for (E e : edgesFromCurrent) {
                if (!visited.contains(e)) {
                    candidates.add(e);
                }
            }
        }
        if (candidates.isEmpty()) {
            // No further edges to traverse; the tour may be incomplete
            break;
        }
        E nextEdge = candidates.get(0);
        visited.add(nextEdge);
        edgeList.add(nextEdge);
        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                       ? graph.getEdgeTarget(nextEdge)
                       : graph.getEdgeSource(nextEdge);
        vertexList.add(nextVertex);
        current = nextVertex;
    }
    if (visited.size() != tour.size()) {
        // Unable to construct a full tour from the provided edge set
        return null;
    }
    V target = vertexList.get(vertexList.size() - 1);
    return new GraphWalk<>(graph, start, target, vertexList, edgeList);
}

