private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel == 0) {
        return; // nothing to do when moving to bucket 0
    }

    // Ensure that the bucket for label 0 exists in the list
    while (bucketsByLabel.size() <= 0) {
        bucketsByLabel.add(new HashSet<>());
    }

    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new HashSet<>();
        bucketsByLabel.set(0, zeroBucket);
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return; // nothing to reload
    }

    for (Integer v : minBucket) {
        labels.set(v, 0);     // update the label of the vertex
        zeroBucket.add(v);    // move the vertex to bucket 0
    }

    minBucket.clear(); // clear the old bucket
}

