private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop must be non‑negative");
    }
    if (outputFrameStack.size() < elements) {
        throw new IllegalStateException(
            "Cannot pop " + elements + " elements from stack of size " + outputFrameStack.size());
    }
    for (int i = 0; i < elements; i++) {
        outputFrameStack.pop();
    }
}

private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("Number of elements to pop must be non-negative");
    }
    int size = stack.size();
    if (elements > size) {
        throw new IllegalStateException("Cannot pop " + elements + " elements from stack of size " + size);
    }
    for (int i = 0; i < elements; i++) {
        stack.remove(size - 1 - i);
    }
}

private void pop(final int elements){
    if (elements < 0){
        throw new IllegalArgumentException("elements must be non‑negative");
    }
    while (elements-- > 0){
        if (stack.isEmpty()){
            throw new IllegalStateException("Stack underflow: attempting to pop from an empty stack");
        }
        stack.pop();
    }
}

