private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev == null) {
        head = next;
    } else {
        prev.next = next;
    }

    if (next == null) {
        tail = prev;
    } else {
        next.prev = prev;
    }

    // Detach the node from the list
    node.prev = null;
    node.next = null;

    size--;
    return true;
}

private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = node.getBefore();
    ListNodeImpl<E> next = node.getAfter();

    if (prev != null) {
        prev.setAfter(next);
    } else {
        this.firstNode = next;
    }

    if (next != null) {
        next.setBefore(prev);
    } else {
        this.lastNode = prev;
    }

    this.size--;

    node.setBefore(null);
    node.setAfter(null);

    return true;
}

