    if (node == null) {
        throw new NullPointerException("node cannot be null");
    }
    final ListNodeImpl<E> next = node.next;
    final ListNodeImpl<E> prev = node.prev;

    if (prev == null) { // node is first
        first = next;
    } else {
        prev.next = next;
    }

    if (next == null) { // node is last
        last = prev;
    } else {
        next.prev = prev;
    }

    node.data = null;
    node.next = null;
    node.prev = null;
    size--;

    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    // If the node to remove is the head
    if (node == head) {
        head = node.next;
        if (head == null) {        // List became empty
            tail = null;
        }
        size--;
        node.next = null;          // Help GC
        return true;
    }

    // Find the predecessor of the node
    ListNodeImpl<E> prev = head;
    while (prev != null && prev.next != node) {
        prev = prev.next;
    }

    // If the node is not found, return false
    if (prev == null) {
        return false;
    }

    // Bypass the node
    prev.next = node.next;
    if (node == tail) {           // Update tail if necessary
        tail = prev;
    }
    size--;
    node.next = null;              // Help GC
    return true;
}

