    node.next = null;
    this.size--;
    return true;
}

public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> ranges = new ArrayList<>();
    if (currentProfiles == null) return ranges;
    for (Profile profile : currentProfiles) {
        if (profile == null) continue;
        List<Segment> segments = profile.getSegments();
        if (segments == null) continue;
        for (Segment segment : segments) {
            if (segment == null) continue;
            List<Snapshot> snapshots = segment.getSnapshots();
            if (snapshots == null) continue;
            for (Snapshot snapshot : snapshots) {
                if (snapshot == null) continue;
                Integer start = snapshot.getSearchStart();
                Integer end = snapshot.getSearchEnd();
                if (start != null && end != null) {
                    ranges.add(new SequenceRange(start, end));
                }
            }
        }
    }
    return ranges;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> sequenceRanges = new ArrayList<>();
    // Obtain the current set of profiles from the repository
    List<Profile> currentProfiles = ProfileRepository.getCurrentProfiles();
    // Iterate over each profile and accumulate its segment ranges
    for (Profile profile : currentProfiles) {
        for (Segment segment : profile.getSegments()) {
            // Construct a SequenceRange from the segment's start and end indices
            SequenceRange range = new SequenceRange(segment.getStartIndex(), segment.getEndIndex());
            sequenceRanges.add(range);
        }
    }
    return sequenceRanges;
}

public List<SequenceRange> buildSequenceRanges(){
    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    java.util.List<ProfileSegment> segments = getCurrentProfileSegments();
    if (segments != null) {
        for (ProfileSegment seg : segments) {
            if (seg == null) continue;
            long start = seg.getStart();
            long end = seg.getEnd();
            if (end < start) continue;
            ranges.add(new SequenceRange(start, end));
        }
    }
    java.util.Collections.sort(ranges, java.util.Comparator.comparingLong(SequenceRange::getStart));
    return ranges;
}

public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> ranges = new ArrayList<>();
    for (SegmentSnapshot ss : getCurrentSegmentSnapshots()){
        int start = ss.getStart();
        int end = ss.getEnd();
        if (start <= end){
            ranges.add(new SequenceRange(start, end));
        }
    }
    return ranges;
}

public List<SequenceRange> buildSequenceRanges() {
    List<SequenceRange> ranges = new ArrayList<>();
    // Iterate over the current profiles to collect all segment ranges
    for (Profile profile : currentProfiles) {
        for (Segment segment : profile.getSegments()) {
            // Assuming Segment provides start and end positions
            int start = segment.getStart();
            int end = segment.getEnd();
            ranges.add(new SequenceRange(start, end));
        }
    }
    return ranges;
}

