public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int lastSeparator;
    int slash = path.lastIndexOf('/');
    int backslash = path.lastIndexOf('\\');
    lastSeparator = slash > backslash ? slash : backslash;
    int dot = path.lastIndexOf('.');
    if (dot > lastSeparator && dot < path.length() - 1) {
        return path.substring(0, dot);
    }
    return path;
}

public static String stripFilenameExtension(String path){
    if (path == null) return null;
    int lastDot = path.lastIndexOf('.');
    if (lastDot == -1) return path;
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    if (lastDot <= lastSeparator) return path;
    return path.substring(0, lastDot);
}

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    // Find the position of the last slash (handles both / and \\, if any)
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find the position of the last dot
    int lastDot = path.lastIndexOf('.');
    // If there is no dot or the dot is before the last slash, no extension
    if (lastDot == -1 || lastDot <= lastSlash) {
        return null;
    }
    return path.substring(0, lastDot);
}

