    if (path == null) return null;
    int slash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int dot = path.lastIndexOf('.');
    if (dot == -1 || dot <= slash) return null;
    return path.substring(0, dot);
}

