                break;
            }
        }

        // If it's a terminator, consume it and end the token.
        if (isTerm) {
            pos++;           // advance past the terminator
            break;
        }

        // Otherwise, add the character to the token and advance.
        token.append(current);
        pos++;
    }

    return token.toString();
}

