private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return Pair.of(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffixList = new ArrayList<>(n);
    long suffixSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        suffixSum += bounds.get(i);
        suffixList.add(0, (int) suffixSum);
    }
    return Pair.of(suffixList, suffixSum);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    int n = bounds.size();
    java.util.List<Integer> suffix = new java.util.ArrayList<>(n);
    long sum = 0;
    for (Integer b : bounds) {
        sum += b;
    }
    long suffixSum = sum;
    for (int i = n - 1; i >= 0; --i) {
        suffix.add(i, (int) suffixSum);
        suffixSum -= bounds.get(i);
    }
    return new Pair<>(suffix, sum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(new java.util.ArrayList<>(), 0L);
    }
    int n = bounds.size();
    java.util.List<Integer> suffix = new java.util.ArrayList<>(n);
    long total = 0;
    for (int i = n - 1; i >= 0; i--){
        total += bounds.get(i);
        suffix.add((int) total);
    }
    java.util.Collections.reverse(suffix);
    return new Pair<>(suffix, total);
}

private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    List<Integer> suffix = new ArrayList<>();
    long totalSum = 0L;
    if (bounds == null || bounds.isEmpty()){
        return new Pair<>(suffix, totalSum);
    }
    int n = bounds.size();
    int[] temp = new int[n];
    int sum = 0;
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        sum += val;
        temp[i] = sum;
        totalSum += val;
    }
    for (int v : temp) {
        suffix.add(v);
    }
    return new Pair<>(suffix, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    long suffixAcc = 0;
    long totalSum = 0;
    int[] suffixArray = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        suffixAcc += val;
        suffixArray[i] = (int) suffixAcc;
        totalSum += val;
    }
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(suffixArray[i]);
    }
    return new Pair<>(suffix, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        return;
    }
    int n = arr.length;
    if (from < 0) {
        from = 0;
    }
    if (to >= n) {
        to = n - 1;
    }
    if (from >= to) {
        return;
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

