private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Preserve the original size of the source list to adjust the destination size after moving all nodes
    final int movedCount = list.size;
    // Start at the first real node in the source list (skipping the head sentinel)
    ListNodeImpl<E> current = list.head.next;
    // Iterate over each node until we reach the tail sentinel
    while (current != list.tail) {
        // Keep a reference to the next node before detaching the current one
        final ListNodeImpl<E> next = current.next;
        // Detach the current node from the source list
        list.removeListNode(current);
        // Attach the node to this (destination) list
        this.addListNode(current);
        // Move to the next node in the original source list
        current = next;
    }
    // After all nodes have been moved, clean up and reset the source list to its empty state
    list.head.next = list.tail;
    list.tail.prev = list.head;
    list.size = 0;
    // Increment the modification counts of both lists to reflect structural changes
    list.modCount += movedCount;
    this.modCount += movedCount;
    // Finally, update this list’s size to reflect the newly added nodes
    this.size = this.size + movedCount;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // If the source list is empty, nothing to do
    if (list.head == null) {
        return;
    }

    // If this list is empty, simply adopt the source list's nodes
    if (this.head == null) {
        this.head = list.head;
        this.tail = list.tail;
        this.size += list.size;

        // Clear the source list
        list.head = null;
        list.tail = null;
        list.size = 0;
        return;
    }

    // Connect this list's tail to the source list's head
    this.tail.next = list.head;
    list.head.prev = this.tail;

    // Update this list's tail and size
    this.tail = list.tail;
    this.size += list.size;

    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list.size == 0){
        return;
    }
    // If this list is empty, just point to list's nodes
    if (this.size == 0){
        this.first = list.first;
        this.last = list.last;
    } else {
        // Link the end of this list to the start of list
        this.last.next = list.first;
        list.first.prev = this.last;
        this.last = list.last;
    }
    this.size += list.size;
    // Empty the source list
    list.first = null;
    list.last = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null || list == this || list.nodeCount == 0) {
        return;
    }
    if (this.nodeCount == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    this.nodeCount += list.nodeCount;
    list.head = null;
    list.tail = null;
    list.nodeCount = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // If the source list is empty or the same as this list, nothing to move.
    if (list == null || list.size == 0 || list == this) {
        return;
    }

    // If this list is empty, simply adopt the source list's nodes.
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Link the tail of this list to the head of the source list.
        this.tail.next = list.head;
        list.head.prev = this.tail;
        // Update the tail of this list to be the tail of the source list.
        this.tail = list.tail;
    }

    // Update the size of this list.
    this.size += list.size;

    // Clear the source list.
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null) {
        return prefix == null;
    }
    if (prefix == null) {
        return false;
    }
    if (prefix.length() > str.length()) {
        return false;
    }
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.regionMatches(false, 0, prefix, 0, prefix.length());
    }
}

