public void putAllWriteable(BeanMap source){
    try {
        // Obtain bean information from the source BeanMap
        BeanInfo beanInfo = Introspector.getBeanInfo(source.getBean());
        for (PropertyDescriptor pd : beanInfo.getPropertyDescriptors()) {
            // Only process properties that have both readable and writable accessors
            Method readMethod = pd.getReadMethod();
            Method writeMethod = pd.getWriteMethod();
            if (readMethod != null && writeMethod != null) {
                String propName = pd.getName();
                // Read the value from the source BeanMap and write it into this BeanMap
                Object value = source.get(propName);
                this.put(propName, value);
            }
        }
    } catch (IntrospectionException e) {
        throw new IllegalArgumentException("Unable to introspect bean for putAllWriteable", e);
    }
}

