        Object value = e.getValue(); // this may throw if the property is write‑only
        try {
            this.put(key, value);
        } catch (IllegalArgumentException ex) {
            // ignore read‑only or write‑only properties that cannot be written to
        } catch (IllegalStateException ex) {
            // ignore properties that are not writable
        }
    }
