public void putAllWriteable(BeanMap map){
    try {
        Object target = this.getBean();
        java.beans.BeanInfo beanInfo = java.beans.Introspector.getBeanInfo(target.getClass());
        java.util.Set<String> writableProps = new java.util.HashSet<>();
        for (java.beans.PropertyDescriptor pd : beanInfo.getPropertyDescriptors()) {
            if (pd.getReadMethod() != null && pd.getWriteMethod() != null) {
                writableProps.add(pd.getName());
            }
        }
        for (Object keyObj : map.keySet()) {
            if (keyObj instanceof String && writableProps.contains(keyObj)) {
                Object value = map.get(keyObj);
                this.put(keyObj, value);
            }
        }
    } catch (java.beans.IntrospectionException e) {
        throw new RuntimeException(e);
    }
}

public void putAllWriteable(BeanMap map){
    for (Object key : map.keySet()){
        if (!(key instanceof String)){
            continue;
        }
        String name = (String) key;
        try {
            Object value = map.get(name);
            try {
                this.setValue(name, value);
            } catch (Exception e) {
                // Destination property is not writable or some other issue – ignore
            }
        } catch (Exception e) {
            // Source property is not readable or some other issue – ignore
        }
    }
}

public void putAllWriteable(BeanMap map) {
    for (Object key : map.keySet()) {
        // Ensure the source property is both readable and writable
        if (map.isReadable(key) && map.isWritable(key)) {
            // Ensure the target property is writable
            if (this.isWritable(key)) {
                this.put(key, map.get(key));
            }
        }
    }
}

