public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) return;
    if (row < 0 || row >= table.getRowCount()) return;

    // Select the desired row
    table.setRowSelectionInterval(row, row);

    // Ensure the selected row is visible
    Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        // Scroll the cell into view inside the JTable
        table.scrollRectToVisible(cellRect);

        // Adjust the viewport position if the pane's viewport is different
        JViewport viewport = pane.getViewport();
        if (viewport != null) {
            viewport.setViewPosition(cellRect.getLocation());
        }
    }

    // Delay repaint until after other UI updates have completed
    SwingUtilities.invokeLater(() -> table.repaint());
}

