public ByteVector putInt(final int intValue){
    int newPos = length + 4;
    if (newPos > cap){
        int newCap = Math.max(cap << 1, newPos);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, length);
        buf = newBuf;
        cap = newCap;
    }
    buf[length]     = (byte)(intValue >>> 24);
    buf[length + 1] = (byte)(intValue >>> 16);
    buf[length + 2] = (byte)(intValue >>>  8);
    buf[length + 3] = (byte)(intValue);
    length = newPos;
    return this;
}

