public void abbreviate(final int nameStart, final StringBuffer buf) {
    final String n = this.name;
    if (n == null || n.isEmpty()) {
        return;
    }
    int len = n.length();
    int start = Math.max(0, nameStart);
    if (start >= len) {
        return;
    }
    boolean needNext = true;
    for (int i = start; i < len; i++) {
        char ch = n.charAt(i);
        if (needNext) {
            buf.append(ch);
            needNext = false;
        }
        if (!Character.isLetterOrDigit(ch) || ch == '_' || ch == '-' || ch == '.' || ch == ' ') {
            needNext = true;
        } else if (Character.isUpperCase(ch) && i > start && Character.isLowerCase(n.charAt(i - 1))) {
            needNext = true;
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null || buf.length() == 0) {
        return;
    }
    String fullName = buf.toString();
    // Ensure nameStart is within bounds
    int startIdx = Math.max(0, Math.min(nameStart, fullName.length()));
    // Find the location of the last dot that is on or after startIdx
    int lastDot = fullName.lastIndexOf('.', startIdx);
    if (lastDot < 0) {
        // No dot found, nothing to abbreviate
        return;
    }
    String prefix = fullName.substring(0, lastDot + 1); // keep trailing dot
    String namePart = fullName.substring(lastDot + 1);   // actual name after last dot
    StringBuilder sb = new StringBuilder();
    // Abbreviate each component of the prefix to its first character
    for (int i = 0; i < prefix.length(); i++) {
        char c = prefix.charAt(i);
        if (i == 0 || prefix.charAt(i - 1) == '.') {
            sb.append(c);
        }
    }
    sb.append(namePart);
    // Replace buffer contents
    buf.setLength(0);
    buf.append(sb.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assume the class has a name field.  If not, replace with your actual source of the
    // name string.  This method abbreviates the portion of the string starting at
    // nameStart by replacing each word with its initial followed by a period.
    if (name == null || buf == null) {
        return;
    }
    final int len = name.length();
    int i = 0;
    while (i < len) {
        // Preserve characters before the abbreviation start unchanged.
        if (i < nameStart) {
            buf.append(name.charAt(i));
            i++;
            continue;
        }
        // Skip any leading whitespace so that we only abbreviate whole words.
        while (i < len && Character.isWhitespace(name.charAt(i))) {
            buf.append(name.charAt(i));
            i++;
        }
        if (i >= len) {
            break;
        }
        // We are at the beginning of a word; append its first letter.
        buf.append(name.charAt(i));
        i++;
        // Skip the rest of the current word.
        while (i <  len && !Character.isWhitespace(name.charAt(i))) {
            i++;
        }
        // Append a period to signify abbreviation.
        buf.append('.');
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null || nameStart < 0 || nameStart > buf.length()) {
        return;
    }
    String name = buf.substring(nameStart).trim();
    if (name.isEmpty()) {
        return;
    }
    String[] parts = name.split("\\s+");
    for (String part : parts) {
        if (!part.isEmpty()) {
            buf.append(Character.toUpperCase(part.charAt(0)));
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
