public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    for (Type bound : bounds) {
        if (bound instanceof Class<?>) {
            return bound;
        }
        if (bound instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) bound).getRawType();
            if (raw instanceof Class<?>) {
                return raw;
            }
        }
        if (bound instanceof TypeVariable<?>) {
            Type resolved = resolveBound((TypeVariable<?>) bound);
            if (resolved != Unknown.class) {
                return resolved;
            }
        }
    }
    return Unknown.class;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A clique is defined by the presence of an edge between every pair of distinct vertices.
    // An empty set or a single vertex is trivially a clique.
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }

    // Convert to a list for indexed access
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size - 1; i++) {
        V v1 = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V v2 = list.get(j);
            // For an undirected graph, containsEdge returns true if an edge exists between the two vertices,
            // regardless of direction. For directed graphs, the definition of a clique typically
            // requires edges in both directions; adjust accordingly if needed.
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }
    V[] arr = (V[]) vertices.toArray(new Object[0]);
    for (int i = 0; i < arr.length; i++) {
        V v1 = arr[i];
        for (int j = i + 1; j < arr.length; j++) {
            V v2 = arr[j];
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A set with 0 or 1 vertex is trivially a clique.
    if (vertices.size() <= 1) {
        return true;
    }

    // Convert the set to a list for indexed traversal.
    List<V> vertexList = new ArrayList<>(vertices);

    // Check every unordered pair of vertices for an edge.
    for (int i = 0; i < vertexList.size(); i++) {
        V vi = vertexList.get(i);
        for (int j = i + 1; j < vertexList.size(); j++) {
            V vj = vertexList.get(j);
            // For undirected graphs, containsEdge checks existence in either direction.
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }

    // All pairs have edges; it's a clique.
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.size() <= 1) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices == null || vertices.isEmpty()) {
        return true;
    }
    Object[] verts = vertices.toArray();
    for (int i = 0; i < verts.length; i++) {
        V u = (V) verts[i];
        for (int j = i + 1; j < verts.length; j++) {
            V v = (V) verts[j];
            // For undirected graphs: containsEdge(u, v) will be true for the undirected edge.
            // For directed graphs: require both directions to consider the pair connected.
            if (!(graph.containsEdge(u, v) && graph.containsEdge(v, u))) {
                return false;
            }
        }
    }
    return true;
}

private java.util.List<Integer> computeLowerBounds(java.util.List<K> keys){
    java.util.List<Integer> bounds = new java.util.ArrayList<>();
    java.util.List<K> sorted = new java.util.ArrayList<>(keys);
    sorted.sort(java.util.Comparator.naturalOrder());
    for (K key : keys) {
        int idx = java.util.Collections.binarySearch(sorted, key);
        if (idx < 0) {
            idx = -idx - 1;
        } else {
            while (idx > 0 && sorted.get(idx - 1).equals(key)) {
                idx--;
            }
        }
        bounds.add(idx - 1);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
