    Collections.sort((List)sorted);
    for (K key : keys) {
        int idx = Collections.binarySearch((List)sorted, key);
        int lb;
        if (idx >= 0) {
            while (idx > 0 && ((Comparable)sorted.get(idx-1)).compareTo(key) == 0) {
                idx--;
            }
            lb = idx - 1;
        } else {
            int insertPoint = -(idx + 1);
            lb = insertPoint - 1;
        }
        lowerBounds.add(lb);
    }
    return lowerBounds;
}

