        if (idx >= 0) {
            // If there are duplicates, move to the last occurrence
            while (idx + 1 < sorted.size() && sorted.get(idx + 1).equals(key)) {
                idx++;
            }
            lowerBounds.add(idx);
        } else {
            int insertionPoint = -idx - 1;
            lowerBounds.add(insertionPoint - 1); // maximum index < key
        }
    }
    return lowerBounds;
}

