private void pop(final String descriptor) {
        String paramDesc;
        if (descriptor.startsWith("(")) {
            int end = descriptor.indexOf(')');
            if (end < 0) {
                throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
            }
            paramDesc = descriptor.substring(1, end);
        } else {
            paramDesc = descriptor;
        }

        int i = 0;
        while (i < paramDesc.length()) {
            char c = paramDesc.charAt(i);

            // skip any number of array brackets
            while (c == '[') {
                i++;
                if (i >= paramDesc.length()) break;
                c = paramDesc.charAt(i);
            }

            if (c == 'L') {
                // object type – consume until ';'
                int semicolon = paramDesc.indexOf(';', i);
                if (semicolon < 0) {
                    throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
                }
                outputStack.pop();          // one slot
                i = semicolon + 1;
            } else if (c == 'J' || c == 'D') {
                // long or double – two slots
                outputStack.pop();
                outputStack.pop();
                i++;
            } else {
                // other primitive – one slot
                outputStack.pop();
                i++;
            }
        }
    }

private void pop(final String descriptor) {
    if (descriptor == null || descriptor.length() == 0) {
        return;
    }
    int i = 0;
    // Handle method descriptor
    if (descriptor.charAt(0) == '(') {
        i = 1; // skip '('
        while (i < descriptor.length() && descriptor.charAt(i) != ')') {
            int slots = 0;
            char c = descriptor.charAt(i);
            // Array type
            if (c == '[') {
                // skip all '['
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                // skip element type (primitive or object)
                if (descriptor.charAt(i) == 'L') {
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++; // skip ';'
                }
                slots = 1;
            }
            // Object type
            else if (c == 'L') {
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                i++; // skip ';'
                slots = 1;
            }
            // Primitive type
            else {
                slots = (c == 'J' || c == 'D') ? 2 : 1;
                i++;
            }
            // Pop the appropriate number of slots
            for (int s = 0; s < slots; s++) {
                stack.pop(); // assumes a stack field named 'stack'
            }
        }
        // Skip ')' and return type (not popped)
        return;
    }
    // Single type descriptor (not a method descriptor)
    int slots = 0;
    char c = descriptor.charAt(i);
    if (c == '[') {
        while (descriptor.charAt(i) == '[') {
            i++;
        }
        if (descriptor.charAt(i) == 'L') {
            while (descriptor.charAt(i) != ';') {
                i++;
            }
            i++; // skip ';'
        }
        slots = 1;
    } else if (c == 'L') {
        while (descriptor.charAt(i) != ';') {
            i++;
        }
        i++; // skip ';'
        slots = 1;
    } else {
        slots = (c == 'J' || c == 'D') ? 2 : 1;
        i++;
    }
    for (int s = 0; s < slots; s++) {
        stack.pop(); // assumes a stack field named 'stack'
    }
}

private void pop(final String descriptor) {
    // Parse the descriptor to obtain the argument types (each argument occupies
    // one or two stack slots).  For each type we pop the corresponding stack
    // slots from the output frame stack.
    final Type[] types = Type.getArgumentTypes(descriptor);
    for (Type type : types) {
        int size = type.getSize();  // size 1 for most types, 2 for long/double
        for (int i = 0; i < size; i++) {
            // Assume the output frame stack is represented by a field named 'stack'.
            stack.pop();
        }
    }
}

