private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) return null;
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort((a, b) -> ((Comparable<? super K>)a).compareTo(b));
    List<Integer> bounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        int pos = Collections.binarySearch(sorted, key, (a, b) -> ((Comparable<? super K>)a).compareTo(b));
        if (pos < 0) {
            pos = -pos - 1;
        } else {
            int i = pos + 1;
            while (i < sorted.size() && ((Comparable<? super K>)sorted.get(i)).compareTo(key) == 0) {
                i++;
            }
            pos = i;
        }
        bounds.add(pos);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>(keys.size());
    // Create a sorted copy of keys
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort(sorted);
    // For each key compute its lower bound (index of first occurrence in sorted list)
    for (K key : keys) {
        int index = sorted.indexOf(key);
        if (index == -1) {
            // If key is not found, use the insertion point as lower bound
            index = Collections.binarySearch(sorted, key);
            if (index < 0) {
                index = -index - 1;
            }
        }
        bounds.add(index);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> upperBounds = new ArrayList<>();
    if (keys == null) {
        return upperBounds;
    }
    // Create a sorted set of unique keys
    TreeSet<K> sortedUnique = new TreeSet<>(keys);
    // Map each unique key to its rank (lower bound index)
    Map<K, Integer> rankMap = new HashMap<>();
    int rank = 0;
    for (K key : sortedUnique) {
        rankMap.put(key, rank++);
    }
    // For each key in the original list, add its rank to the result
    for (K key : keys) {
        Integer bound = rankMap.get(key);
        // If the key is null or not present, we can assign -1 or any sentinel
        upperBounds.add(bound == null ? -1 : bound);
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        // In absence of a natural ordering for K, we return the maximum integer value as an upper bound.
        upperBounds.add(Integer.MAX_VALUE);
    }
    return upperBounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> result = new java.util.ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int idx = java.util.Collections.binarySearch(keys, key);
        if (idx >= 0) {
            while (idx < keys.size() - 1 && keys.get(idx + 1).equals(key)) {
                idx++;
            }
            idx++; // upper bound is after the last equal element
        } else {
            idx = -idx - 1; // insertion point for upper bound
        }
        result.add(idx);
    }
    return result;
}

