public static String applyRelativePath(String path, String relativePath) {
    // Split the given path into components, respecting leading slash for absolute paths
    String[] pathParts = path.split("/");
    java.util.ArrayList<String> stack = new java.util.ArrayList<>();

    boolean pathIsAbsolute = path.startsWith("/");
    boolean pathEndsWithSlash = path.endsWith("/");

    // Determine how many parts of the original path are treated as directory components
    int endIndex = pathEndsWithSlash ? pathParts.length : pathParts.length - 1;

    for (int i = 0; i < endIndex; i++) {
        String part = pathParts[i];
        if (!part.isEmpty()) {
            stack.add(part);
        }
    }

    // Process the relative path segments
    if (relativePath != null) {
        String[] relParts = relativePath.split("/");
        for (String part : relParts) {
            if (part.isEmpty() || part.equals(".")) {
                continue; // No change for current directory
            } else if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.remove(stack.size() - 1);
                }
            } else {
                stack.add(part);
            }
        }
    }

    // Construct the resulting path
    StringBuilder result = new StringBuilder();
    if (pathIsAbsolute) {
        result.append("/");
    }

    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // Preserve a trailing slash if the relative path ended with one
    if (relativePath != null && !relativePath.isEmpty() && relativePath.endsWith("/")) {
        result.append("/");
    }

    // If nothing was added and path was relative, ensure we return at least "."
    if (result.length() == 0) {
        result.append(".");
    }

    return result.toString();
}

