    java.util.List<String> components = new java.util.ArrayList<>();
    // Split the base path
    String[] splitPath = path.split("/", -1); // keep trailing empty parts
    for (String part : splitPath) {
        components.add(part);
    }
    // If the base path does not end with '/' and the last component is not empty,
    // assume the last component is a file and drop it.
    if (!path.endsWith("/") && components.size() > 0 && !components.get(components.size() - 1).isEmpty()) {
        components.remove(components.size() - 1);
