            if (components.size() > 1) { // do not remove root
                components.remove(components.size() - 1);
            }
        } else {
            components.add(part);
        }
    }
    // Build the resulting path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < components.size(); i++) {
        String comp = components.get(i);
        if (i == 0) {
            if (comp.isEmpty()) {
