    // If the path ends with '/', treat it as a directory; otherwise discard the file component
    int baseLength = baseComponents.length;
    boolean endsWithSlash = path.endsWith("/");
    int limit = endsWithSlash ? baseLength : baseLength - 1;
    if (limit < 0) {
