}

Edge edgeToNext(){
    Node previous = getPreviousNode();
    Node next = getNextNode();
    if (previous == null || next == null) {
        return null;
    }
    // Resolve any virtual nodes to their real counterparts
    if (previous.isVirtual()) {
        previous = previous.getRealNode();
    }
    if (next.isVirtual()) {
        next = next.getRealNode();
    }
    // Iterate over edges incident to the previous node to find the connecting edge
    for (Edge e : previous.getEdges()) {
        if (e.getSource() == next || e.getTarget() == next) {
            return e;
        }
    }
    // If no edge is found, return null
    return null;
}

