protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }

    // Render the event into a string
    String msg;
    if (layout != null) {
        msg = layout.format(event);
    } else {
        msg = event.getRenderedMessage();
    }
    if (msg == null) {
        msg = "";
    }
    msg += "\n";

    // Send to all connected clients
    synchronized (clientWriters) {
        Iterator<PrintWriter> it = clientWriters.iterator();
        while (it.hasNext()) {
            PrintWriter out = it.next();
            try {
                out.print(msg);
                out.flush();
            } catch (Exception ex) {
                // Remove broken writer to avoid repeated failures
                it.remove();
            }
        }
    }
}

protected void append(LoggingEvent event) {
    String msg = event.getFormattedMessage();
    synchronized (writers) {
        Iterator<PrintWriter> it = writers.iterator();
        while (it.hasNext()) {
            PrintWriter pw = it.next();
            try {
                pw.println(msg);
                pw.flush();
            } catch (Exception e) {
                // Remove defective writer
                it.remove();
                try {
                    pw.close();
                } catch (Exception ignored) {}
            }
        }
    }
}

