private void checkIfPackedField() throws IOException {
    // Packed repeated fields are encoded with wire type 2 (length‑delimited).
    // Determine the wire type of the current field from its tag.
    int wireType = (currentTag & 0x07);
    if (wireType == 2) {
        // Internal flag indicating that we are now reading a packed field.
        inPackedField = true;
    } else {
        inPackedField = false;
    }
}

private void checkIfPackedField() throws IOException {
    // If this field is marked as packed (repeated and length-delimited), keep track that
    // we are now reading a packed field.
    if (wireType == 2 && isPackedField(fieldNumber)) {
        readingPacked = true;
    } else {
        readingPacked = false;
    }
}

private void checkIfPackedField() throws IOException {
    // Determine the wire type of the current tag.
    int wireType = WireFormat.getTagWireType(this.currentTag);

    // In Protobuf, a packed repeated field is encoded as a length‑delimited (wire type 2).
    // If we encounter such a tag, update the internal state to indicate we are now reading
    // a packed field and record the length of the packed data so that subsequent reads
    // know when to stop.
    if (wireType == WireFormat.WIRETYPE_LENGTH_DELIMITED) {
        // Mark that the next values belong to a packed field.
        this.isPackedField = true;
        // Read the length of the packed data (a varint).
        this.packedFieldRemaining = readRawVarint32();
    } else {
        // Not a packed field – ensure the state reflects that.
        this.isPackedField = false;
    }
}

private void checkIfPackedField() throws IOException {
    // Check if the last tag denotes a length‑delimited field
    // and the field number matches the current repeated field number.
    if ((lastTag & 0x07) == WireFormat.WIRETYPE_LENGTH_DELIMITED
        && WireFormat.getTagFieldNumber(lastTag) == currentFieldNumber) {
        // Read the length of the packed data
        int length = input.readRawVarint32();
        // Store the packed data for later processing
        packedData = input.readRawBytes(length);
        // Update internal state to indicate that packed data has been read
        packed = true;
    }
}

private void checkIfPackedField() throws IOException {
    // Determine whether the next field to be read is a packed repeated field.
    // If the current tag indicates a length‑delimited wire type, the field
    // may be packed.  When it is packed we read the length prefix, set the
    // internal limit for the packed block, and flag that we are reading a
    // packed field.
    int wireType = this.currentTag & 0x07;
    int fieldNumber = this.currentTag >>> 3;

    // Packed fields are only encoded with the LENGTH_DELIMITED wire type.
    if (wireType != WireFormat.WIRETYPE_LENGTH_DELIMITED) {
        return;
    }

    // Look up the descriptor for this field.  If it does not exist or is
    // not marked as a packed repeated field, nothing further needs to be
    // done.
    FieldDescriptor desc = this.descriptorPool.findFieldByNumber(fieldNumber);
    if (desc == null || !desc.isRepeated() || !desc.isPacked()) {
        return;
    }

    // The packed data is prefixed by its length.  Read it and set the
    // internal bound so that subsequent reads consume only the packed
    // data.  Mark that we are within a packed field.
    int len = this.readRawVarint32();
    this.packedFieldLimit = this.getPosition() + len;
    this.isReadingPacked = true;
}

