public int readTag() throws IOException {
    int tag = 0;
    int shift = 0;
    while (true) {
        int b = in.read();
        if (b == -1) {
            // Reached EOF: return zero as special value
            return 0;
        }
        tag |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 32) {
            throw new IOException("Malformed varint");
        }
    }
    return tag;
}

public int readTag() throws IOException {
    int first = read();
    if (first == -1) {
        return 0; // EOF reached before reading any byte
    }
    int tag = first;
    if ((first & 0x80) != 0) { // varint continues
        tag = first & 0x7F;
        int shift = 7;
        while (true) {
            int b = read();
            if (b == -1) {
                throw new IOException("EOF while reading tag");
            }
            tag |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                break;
            }
            shift += 7;
            if (shift >= 32) {
                throw new IOException("Tag is too long");
            }
        }
    }
    return tag;
}

