private String buildContentRange() {
    // Build the Content-Range header value in the format: "bytes start-end/total"
    // Assumes fields `start`, `end`, and `totalSize` (or similar) exist in this class.
    // If total size is not known, use '*'.
    if (totalSize <= 0) {
        return "bytes " + start + "-" + end + "/*";
    }
    return "bytes " + start + "-" + end + "/" + totalSize;
}

private String buildContentRange() {
    // Assumes the class has fields: contentRangeStart, contentRangeEnd, and contentLength.
    // Adjust the field names if necessary.
    long start = contentRangeStart;
    long end   = contentRangeEnd;
    long total = contentLength;
    return "bytes " + start + "-" + end + "/" + total;
}

private String buildContentRange() {
    // Build the Content-Range header value in the format:
    //   "bytes <start>-<end>/<total>"
    // Assumes the class has the following fields:
    //   long rangeStart   // start byte position (inclusive)
    //   long rangeEnd     // end byte position (inclusive)
    //   long contentLength // total length of the resource, or -1 if unknown
    //
    // If the range information is not set, return null.

    if (rangeStart < 0 || rangeEnd < 0) {
        return null;
    }

    // Adjust rangeEnd if it exceeds contentLength
    if (contentLength > 0 && rangeEnd >= contentLength) {
        rangeEnd = contentLength - 1;
    }

    // If contentLength is unknown, use the end of the range as total
    long total = contentLength > 0 ? contentLength : rangeEnd + 1;

    return String.format("bytes %d-%d/%d", rangeStart, rangeEnd, total);
}

private String buildContentRange() {
    // Assuming these fields exist in the class.
    long start = this.rangeStart;   // start byte of requested range
    long end = this.rangeEnd;       // end byte inclusive
    long total = this.totalLength;  // total size of resource, -1 if unknown
    if (start < 0 || end < start) {
        throw new IllegalStateException("Invalid range: " + start + "-" + end);
    }
    if (total < 0) {
        return "bytes " + start + "-" + end + "/*";
    }
    return "bytes " + start + "-" + end + "/" + total;
}

private String buildContentRange(){
    long start = this.startOffset;   // assumed field holding start byte index
    long end   = this.endOffset;     // assumed field holding end byte index
    long total = this.totalSize;     // assumed field holding total size of the resource

    if (total <= 0) return null;     // no content to describe

    // Ensure values are within bounds
    if (start < 0) start = 0;
    if (end < start) end = start;
    if (end >= total) end = total - 1;

    return String.format("bytes %d-%d/%d", start, end, total);
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("File must not be null");
    }
    // Read all snapshots from the given file
    List<ThreadSnapshot> allSnapshots = parseFromFile(file);
    // If no time ranges specified, return all snapshots
    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }
    // Collect snapshots that fall within any of the specified time ranges
    List<ThreadSnapshot> filtered = new ArrayList<>(allSnapshots.size());
    for (ThreadSnapshot snapshot : allSnapshots) {
        long ts = snapshot.getTimestamp();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
                filtered.add(snapshot);
                break;
            }
        }
    }
