            int firstSpace = line.indexOf(' ');
            if (firstSpace < 0) {
                continue;
            }
            String tsStr = line.substring(0, firstSpace);
            String data = line.substring(firstSpace + 1);
            long timestamp;
            try {
                timestamp = Long.parseLong(tsStr);
